COLLDATA("sh20859","ar",[[1,"كتاب علوم الحديث"],[2,"٩٧٦ -"],[3,"فضل أهل الحديث"],[4,"قال موسى بن هارون: سمعت أحمد بن حنبل رحمه الله، وسئل عن معنى هذا الحديث (١)، فقال: إن لم تكن هذِه الطائفة المنصورة أصحاب الحديث فلا أدري من هم."],[5,"\"معرفة علوم الحديث\" (٢)"],[6,"٩٧٧ -"],[7,"من هو صاحب الحديث"],[8,"؟"],[9,"قال أبو القاسم بن منيع: أردت الخروج إلى سويد بن سعيد، فقلت لأحمد بن حنبل يكتب لي إليه فكتب: وهذا رجل يكتب الحديث."],[10,"فقلت: يا أبا عبد اللَّه، خدمتي لك ولزومي، لو كتبت هذا رجلٌ من أصحاب الحديث؟"],[11,"فقال: صاحب الحديث عندنا من يستعمل الحديث."],[12,"\"المناقب\" لابن الجوزي ص ٢٦٨"],[13,"(١) يعني قوله -صلى الله عليه وآله وسلم-: \"لا يزال ناس من أمتي منصورين، لا يضرهم من خذلهم حتى تقوم الساعة\" رواه أحمد ٣/ ٤٣٦ والترمذي (٢١٩٢) وابن ماجه (٦) من حديث معاوية ابن قرة عن أبيه. قال الترمذي: حديث حسن صحيح. وقال الألباني في \"الصحيحة\" (٤٠٣): وهو على شرط الشيخين."],[14,"الجزء: 15 - الصفحة: 413"],[15,"باب ما جاء في أقسام الحديث"],[16,"٩٧٨ - ما جاء في أصح الأسانيد"],[17,"قال أبو العباس أَحمد بن محمد بن يزيد البراثي: سمعت خلفا البزار يقول: سألت أحمد بن حنبل أي الأسانيد أثبت؟"],[18,"قال: أيوب، عن نافع، عن ابن عمر. وإِن كان من حديث حماد بن زيد فيا لك."],[19,"\"المناقب\" لابن الجوزي ١١٩"],[20,"٩٧٩ - الحديث الغريب"],[21,"وروى أبو إسحاق في تعاليقه عن أبي بكر النقاش، عن محمد بن سعيد، عن محمد بن سهل بن عسكر، سمعت أحمد بن حنبل رحمه الله يقول: إذا سمعت أصحاب الحديث يقولون: هذا حديث غريب أو فائدة، فاعلم أنه خطأ، وإذا سمعتهم يقولون: هذا حديث لا شيء، فاعلم أنه صحيح."],[22,"\"العدة\" ٣/ ٩٣٠، \"شرح علل الترمذي\" لابن رجب ١/ ٤٠٨"],[23,"قال علي بن عثمان النفيلي: قال. أحمد: شر الحديث الغرائب التي لا يعمل بها ولا يعتمد عليها."],[24,"وقال المروذي سمعت أحمد يقول: تركوا الحديث وأقبلوا على الغرائب، ما أقل الفقه فيهم؟ !"],[25,"وقال أحمد بن يحيى سمعت أحمد غير مرة يقول: لا تكتبوا هذِه الأحاديث الغرائب فإنها مناكير وعامتها عن الضعفاء."],[26,"\"شرح علل الترمذي\" لابن رجب ١/ ٤٠٨ - ٤٠٩"],[27,"الجزء: 15 - الصفحة: 414"],[28,"٩٨٠ - الحديث المعنعن"],[29,"نقل أبو الحارث وعبد اللَّه عن الإمام أحمد، قال: ما رواه الأعمش عن إبراهيم، عن علقمة، عن عبد اللَّه، عن النبي -صلى الله عليه وآله وسلم- فهو ثابت، وما رواه الزهري عن سالم، عن أبيه. وداود، عن الشعبي (١)، عن علقمة، عن عبد اللَّه، ثابت."],[30,"\"العدة\" ٣/ ٩٨٦"],[31,"٩٨١ - هل الحديث المعنعن والمؤنن سواء؟"],[32,"؟"],[33,"قال أبو داود: سمعت أحمد يقول: كان مالك -زعموا- يرى عن فلان وأن فلانا سواء، ذكر أحمد مثل حديث جابر أن سليكًا جاء والنبي -صلى الله عليه وآله وسلم- يخطب (٢). أو عن جابر، عن سليك: أنه جاء."],[34,"سمعت أحمد قيل له: إن رجلًا قال: عروة أن عائشة، وعروة عن عائشة قالت: يا رسول اللَّه. .، وعن عروة عن عائشة؛ سواء؟ فقال: كيف هو سواء؟ ! أي: ليس هو بسواء."],[35,"\"مسائل أبي داود\" (١٩٧٨)"],[36,"(١) في \"العدة\": (أشعث) والصواب الشعبي، وسيأتي بعد خمس صفحات. (٢) رواه الإمام أحمد ٣/ ٢٩٧، ومسلم (٨٧٥)، ورواه البخاري (٩٣٠) ولم يسمَّ الرجل سليكًا."],[37,"الجزء: 15 - الصفحة: 415"],[38,"٩٨٢ - حكم زيادة الثقة"],[39,"قال أحمد بن القاسم: سألت أبا عبد اللَّه رحمه الله عن مسألة في فوات الحج، فقال: فيها روايتان: إحداهما: فيها زيادة دم، قال أبو عبد اللَّه: والزائد أولى أن يؤخذ به."],[40,"قال: ومذهبنا في الأحاديث: إذا كانت الزيادة في أحدهما، أخذنا بالزيادة."],[41,"ونقل الميموني عنه أنه قال: نقل أن النبي -صلى الله عليه وآله وسلم- دخل الكعبة ولم يصل (١)، ونقل أنه صلى (٢)، فهذا يشهد أنه صلى."],[42,"وابن عمر يقول: لم يقنت في الفجر (٣)، وغيره يقول: قنت (٤)، فهذِه شهادة عليه أنه قنت، وحديث أنس: لم يأن لرسول اللَّه -صلى الله عليه وآله وسلم- أن يخضب (٥)، وقوم يقولون: قد خضب (٦)، فهذِه شهادة على الخضاب، فالذي يشهد على النبي -صلى الله عليه وآله وسلم-، فهو أوكد."],[43,"(١) رواه الإمام أحمد ٢/ ٣، ٣٣، والبخاري (٣٩٧)، ومسلم (١٣٢٩) من حديث ابن عمر. (٢) رواه الإمام أحمد ١/ ٢٣٧، والبخاري (٣٩٨)، ومسلم (١٣٣١) من حديث ابن عباس. وانظر للجمع بين الروايتين: \"فتح الباري\" ٣/ ٤٦٨ - ٤٦٩. (٣) رواه عبد الرازق ٣/ ١٠٧ (٤٩٥٤)، والطحاوي في \"شرح معاني الآثار\" ٢/ ٢٤٦. (٤) روى غير واحد من أصحاب النبي -صلى الله عليه وآله وسلم- أنه قنت في الفجر منهم: أنس بن مالك: رواه الإمام أحمد ٣/ ١١٣، والبخاري (١٠٠١)، ومسلم (٦٧٧/ ٢٩٨). البراء بن عازب: رواه الإمام أحمد ٤/ ٢٨٠، ومسلم (٦٧٨). (٥) رواه الإمام أحمد ٣/ ٢٢٧، والبخاري (٥٨٩٥)، ومسلم (٢٣٤١). (٦) رواه الإمام أحمد ٢/ ١٧ - ١٨، والبخاري (١٦٦) من حديث ابن عمر أنه -صلى الله عليه وآله وسلم- كان يخضب."],[44,"الجزء: 15 - الصفحة: 416"],[45,"نقل الأثرم وإبراهيم بن الحارث والمروذي: إذا تبايعا فخير أحدهما صاحبه بعد البيع، فهل يجب، فقال: هكذا في حديث ابن عمر (١)."],[46,"قيل له: أتذهب إليه، قال: لا، أنا أذهب إلى الأحاديث الباقية، الخيار لهما ما لم يتفرقا، ليس فيها شيء من هذا."],[47,"وقال في رواية أبي طالب: كان الحجاج بن أرطاة من الحفاظ."],[48,"قيل له: فلم هو عند الناس ليس بذاك، قال: لأن في حديثه زيادة على حديث الناس، ما يكاد له حديث إلَّا فيه زيادة."],[49,"\"العدة\" ٣/ ١٠٠٤ - ١٠٠٧، \"المسودة\" ١/ ٥٩٠ - ٥٩٢."],[50,"وقال -في رواية صالح-: قد أنكر على مالك هذا الحديث -يعني: زيادته: \"من المسلمين\" في حديث نافع عن ابن عمر قال: فرض رسول اللَّه -صلى الله عليه وآله وسلم- زكاة الفطر من رمضان على كل حر أو عبد أذكر أو أنثى من المسلمين صاعًا من تمر أو صاعًا من شعير- ومالك إذا انفرد بحديث هو ثقة، وما قال أحد ممن قال بالرأي أثبت منه -يعني: في الحديث."],[51,"\"شرح علل الترمذي\" لابن رجب ١/ ٤٢٢"],[52,"= وروى الإمام أحمد ٢/ ٢٢٧، ٤/ ١٦٣، وأبو داود (٤٢٠٨)، والنسائي ٨/ ١٤١ من حديث أبي مثة قال: الترمذي في \"الشمائل\" (٤٣، ٤٥) هذا أحسن شيء روي في هذا الباب وأفسر؛ لأن الروايات الصحيحة أن النبي -صلى الله عليه وآله وسلم- لم يبلغ الشيب وصححه الألباني في \"مختصر الشمائل\" (٣٦، ٣٧). (١) رواه الإمام أحمد ٢/ ٩، والبخاري (٢١٠٧)، ومسلم (١٥٣١)."],[53,"الجزء: 15 - الصفحة: 417"],[54,"٩٨٣ - معرفة من يرجع إلى قوله عند اختلاف الثقات"],[55,"نقل عنه المروذي أنه سئل -عن نافع وسالم- إذا اختلفا فلأيهما يقضي؛ فقال: كلاهما ثبت ولم ير أن يقضي لأحدهما على الآخر."],[56,"\"شرح علل الترمذي\" لابن رجب ٢/ ٤٧٢"],[57,"٩٨٤ - ترجيح المراسيل بعضها على بعض"],[58,"قال أحمد -في رواية أبي الحارث-: مرسلات سعيد بن المسيب صحاح، لا يُرى أصح من مرسلاته، فأما الحسن وعطاء، فليس بذلك، هو أضعف المرسلات، كأنهما كانا يأخذان من كلٍّ."],[59,"وقال أحمد في رواية الفضل بن زياد: أما مرسلات عطاء، ففيها شيء، وأما ابن سيرين فما أحسن مخرجه أيضًا. ومرسلات سعيد بن المسيب أصح المرسلات، ومرسلات إبراهيم النخعي لا بأس بها. وليس في المرسلات أضعف من مرسلات الحسن وعطاء بن أبي رباح؛ كأنهما كانا يأخذان من كلٍّ."],[60,"وقال أحمد في رواية مهنا وقد سأله عن مرسلات سعيد بن جبير أحب إليك أم مرسلات عطاء؟"],[61,"قال: مرسلات سعيد بن جبير أقرب، وهي أحب إليّ من مرسلات عطاء."],[62,"وسأله: عن مرسلات سعيد بن جبير أحب إليك أم مرسلات مجاهد؟"],[63,"فقال: مرسلات سعيد."],[64,"وسأله: عن مرسلات مجاهد أحب إليك أم مرسلات عطاء؟"],[65,"الجزء: 15 - الصفحة: 418"],[66,"فقال مرسلات مجاهد؛ لأن عطاء روى عمن هو دونه، ومجاهد لم يرو عمن هو دونه."],[67,"وقال أحمد في رواية أبي الحارث: مرسلات عطاء فيها شيء."],[68,"وقال أحمد في رواية مهنا وقد سأله عن مرسلات طاوس أحب إليك أو مرسلات أبي إسحاق؟"],[69,"قال: مرسلات طاوس."],[70,"وسأله عن مرسلات إسماعيل بن أبي خالد أحب إليك أم مرسلات عمرو بن دينار؟"],[71,"فقال: إسماعيل بن أبي خالد لا يبالي عمن حدث، عن أشعث بن سوار وعن مجاهد، وعمرو بن دينار لا يروي إلَّا عن ثقة، مرسلات عمرو أحب إليّ."],[72,"وسأله: أيما أحب إليك: إبراهيم عن عليّ، أو مجاهد عن عليّ؟"],[73,"قال: إبراهيم عن عليّ؛ لأن هذا كان مقيمًا، وكان مجاهد إنما تقع إليهم الأخبار إلى الكوفة."],[74,"وقال أحمد في رواية أبي الحارث وقد سأله عن مرسلات النخعي؟"],[75,"قال: ما أصلحها، ليس بها بأس، أصلح من مرسلات الحسن."],[76,"وسأله مهنا: لم كرهت مرسلات الأعمش؟"],[77,"قال: كان الأعمش لا يبالي عمن حدث."],[78,"قيل له: فإن له رجلًا ضعيفًا غير إسماعيل بن مسلم ويزيد الرقاشي؟ قال: نعم، كان يحدث عن عتاب بن إبراهيم."],[79,"وسأله أيضًا: عن مرسلات الأعمش، وسليمان النخعي، ويحيى بن أبي كثير؟"],[80,"الجزء: 15 - الصفحة: 419"],[81,"قال: مرسلات يحيى بن كثير أحب إليّ."],[82,"وقال أحمد في رواية إسحاق بن إبراهيم، وقد سأله عن مراسيل يحيى بن أبي كثير؟"],[83,"فقال: لا تعجبني؛ لأنه يروي عن رجال صغار ضعاف."],[84,"وقال أحمد في رواية أبي طالب، وقد سأله عن رجل ما قال الحسن، قال رسول اللَّه -صلى الله عليه وآله وسلم-، وجدناه من حديث أبي هريرة وعائشة وسَمُرة، قال: صدق."],[85,"وقال أحمد في رواية مهنا، وقد سأله: هل شيء يجيء عن الحسن. قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-؟ قال: هو صحيح، ما نكاد نجدها إلَّا صحيحة."],[86,"وقال أحمد في رواية أبي الحارث: مرسلات ابن سيرين صحاح حسنة المخرج."],[87,"وقال أحمد في رواية مهنا، وقد سأله عن مرسلات سفيان، فقال: كان سفيان لا يبالي عمن روى."],[88,"وسأله: عن مرسلات مالك بن أنس؟ قال: هي أحب إليّ."],[89,"\"العدة\" ٣/ ٩٢٠ - ٩٢١"],[90,"وقال أحمد -في رواية أبي الحارث وعبد اللَّه-: ما رواه الأعمش، عن إبراهيم، عن علقمة، عن عبد اللَّه، عن النبي -صلى الله عليه وآله وسلم- فهو ثابت، وما رواه الزهري، عن سالم، عن أبيه، وداود عن الشعبي، عن علقمة، عن عبد اللَّه، عن النبي -صلى الله عليه وآله وسلم- ثابت."],[91,"\"المسودة\" ١/ ٥١٨ - ٥١٩"],[92,"وقال أحمد -في رواية الميموني وحنبل عنه-: مرسلات سعيد ابن المسيب صحاح لا نرى أصح من مرسلاته."],[93,"الجزء: 15 - الصفحة: 420"],[94,"زاد الميموني: وأما الحسن وعطاء فليس هي بذاك، هي أضعف المراسيل كلها، فإنهما كانا يأخذان عن كل."],[95,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٩٠"],[96,"٩٨٥ - قول الصحابي: (من السنة) هل يقتضي سنة النبي -ﷺ- ويكون بمنزلة المرفوع؟ وكذلك قول التابعي: (من السنة) هل يكون بمنزلة المرسل؟"],[97,"؟"],[98,"نقل أبو النضر العجلي عن أحمد: في جراحات النساء مثل جراحات الرجال، حتى تبلغ الثلث، فإذا زاد فهو على النصف من جراحات الرجل، قال: هو قول زيد بن ثابت (١)، وقول على: كله على النصف (٢)."],[99,"قيل له: كيف لم تذهب إلى قول علي؟"],[100,"قال: لأن هذا -يعني: قول زيد- ليس بقياس، قال سعيد بن المسيب: هو السنة (٣)."],[101,"ونقل عنه البرزاطي لما روي الحديث عن ابن عمر أنه قال: مضت"],[102,"(١) رواه ابن أبي شيبة ٥/ ٤١١ (٢٧٤٨٨)، والبيهقي ٨/ ٩٦. (٢) رواه ابن أبي شيبة ٥/ ٤١١ (٢٧٩٤٢)، والبيهقي ٨/ ٩٦، وصحح إسناده الألباني في \"الإرواء\" ٧/ ٣٠٧. (٣) رواه مالك في \"الموطأ\" ص ٥٣٦، وعبد الرزاق ٩/ ٣٦٤ - ٣٩٥ (١٧٧٤٩)، وابن أبي شيبة ٥/ ٤١١ - ٤١٢ (٢٧٤٩٥)، والبيهقي ٨/ ٩٦. قال الألباني في \"الإرواء\" (٢٥٥٥): وهذا سند صحيح إلى سعيد."],[103,"الجزء: 15 - الصفحة: 421"],[104,"السنة أن ما أدركت الصفقة حيًا مجموعًا فهو من مال المبتاع، فقال بعد هذا: صار الحديث مرفوعًا بقوله: مضت السنة، ويدخل في المسند (١)."],[105,"\"العدة في أصول الفقه\" ٣/ ٩٩٣ - ٩٩٤"],[106,"٩٨٦ - الحديث المدلس"],[107,"قال حرب: سألتُ أحمد عن التدليس في الحديث فكرهه، وقال: أقل شيء أنه يتزيد أو يتزين."],[108,"قال حرب: أنا أشك."],[109,"\"مسائل حرب\" ص ٣٤٤"],[110,"٩٨٧ - الحديث المنكر"],[111,"قال ابن هانئ: قيل له: فهذِه الفوائد التي فيها المناكير، ترى أن يكتب الحديث المنكر؟"],[112,"قال: المنكر أبدًا منكر."],[113,"\"مسائل ابن هانئ\" (١٩٢٥)."],[114,"(١) تعقب شيخ الإسلام المؤلف في هذا، حيث قال في \"المسودة\" ص (٢٩٥): قلت: ويغلب على ظني أن هذا الضرب لم يذكره أحمد في الحديث المسند، فلا يكون عنده مرفوعًا."],[115,"الجزء: 15 - الصفحة: 422"],[116,"باب الإسناد"],[117,"٩٨٨ - الأمر بالتفتيش عن الأسانيد، وأن الإسناد من الدين"],[118,"قال محمد بن الحسين البغدادي: سمعت أحمد بن حنبل يقول: سمعت يحيى بن سعيد يقول: الإسناد من الدين. قال يحيى: وسمعت شعبة يقول: إنما تعلم صحة الحديث بصحة الإسناد."],[119,"\"شرح علل الترمذي\" لابن رجب ١/ ٥٨"],[120,"٩٨٩ - طلب علو الإسناد"],[121,"روى أبو بكر الخلال، عن حرب بن إسماعيل، قال: سئل أحمد عن الرجل يطلب الإسناد العالي، فقال: طلب الإسناد العالي سنة عمن سلف؛ لأن أصحاب عبد اللَّه كانوا يرحلون من الكوفة إلى المدينة فيتعلمون من عمر ويسمعون منه."],[122,"وقال عمار بن رجاء: سمعت أحمد بن حنبل يقول: طلب إسناد العلو من السنة."],[123,"\"المناقب\" ص ٢٦٣"],[124,"٩٩٠ - رواية الأكابر عن الأصاغر"],[125,"قال ابن هانئ: وقال: أرى مروان قد روى وهو أصغر من مروان، وأصغر من وكيع."],[126,"\"مسائل ابن هانئ\" (٢٢٣١)"],[127,"الجزء: 15 - الصفحة: 423"],[128,"قال عبد اللَّه: قلت لأبي: إن يحيى بن معين يطعن علي عامر بن صالح هذا، قال: يقول ماذا؟"],[129,"قلت: رآه يسمع من حجاج."],[130,"قال: قد رأيت أنا حجاج يسمع من هشيم، وهذا عيب يسمع الرجل ممّن هو أصغر منه وأكبر."],[131,"\"فضائل الصحابة\" ٢/ ١٠٧٨ (١٥٨٩)"],[132,"قال ابن الجوزي: أخبرنا أبو منصور القزاز، قال: أنا أبو بكر بن ثابت، قال: أنا أبو الفرج الطناجيري، قال: ثنا عمر بن أحمد الواعظ، قال: ثنا عبد اللَّه بن سليمان بن الأشعث، قال: ثنا أبي، قال: ثنا محمد بن عمرو الرازي، قال: ثنا عبد الرحمن بن قيس، عن حماد بن سلمة، عن أبي العشراء الدارمي، عن أبيه أن رسول اللَّه -صلى الله عليه وآله وسلم- سئل عن العتير فحسنها (١)، قال: قال ابن أبي داود: قال أبي فذكرته لأحمد بن حنبل فاستحسنه وقال: هذا حديث غريب، وقال لي: اقعد، فدخل فأخرج محبرة وقلما وورقة وقال: أمله عليّ، فكتبه عني، ثم شهدته يومًا آخر وجاءه أبو جعفر بن أبي سمينة، فقال أحمد بن حنبل: يا أبا جعفر، عند أبي داود حديث غريب اكتبه عنه، فسألني فأمليته عليه."],[133,"\"المناقب\" ص ٦٥ - ٦٦"],[134,"(١) رواه الطبراني ٧/ ١٦٨، وقال الهيثمي في \"المجمع\" ٤/ ٣٠: فيه عبد الرحمن بن قيس الضبي ولم أجد من ترجمه وبقية رجاله ثقات."],[135,"الجزء: 15 - الصفحة: 424"],[136,"فصل: من حدث عن الإمام أحمد من مشايخه ومن الأكابر"],[137,"٩٩١ - عبد الرزاق بن همام الصنعاني"],[138,"قال ابن الجوزي: أَنبأَنا محمد بن عبد الملك بن خيرون، قال: أَنبأَنا أَبو بكر أَحمد بن علي بن ثابت، قال: ثنا أَبو طالب يحيى بن علي بن الطيب العجلي، قال: أَنا أَبو يعقوب يوسف بن إبراهيم بن موسى السهمي، قال: ثنا عبد اللَّه بن محمد بن مسلم، قال: ثنا مهدي بن الحارث، قال: ثنا أَبو عبد اللَّه القصار، قال: أَنا عبد الرزاق، قال: أَنا أَحمد بن حنبل، عن الوليد -يعني: ابن مسلم- عن زيد بن واقد، قال: سمعت نافعا مولى ابن عمر، أن ابن عمر كان إِذا رأى مصليًا لا يرفع يديه في الصلاة حصبه وأَمره أن يرفع."],[139,"\"المناقب لابن الجوزي\" ص ١١٥"],[140,"٩٩٢ - إسماعيل ابن علية"],[141,"ذكر أَبو بكر الخلال، أَنه روى عن أَحمد."],[142,"\"المناقب\" ص ١١٥"],[143,"٩٩٣ - وكيع بن الجراح"],[144,"قال ابن الجوزي: وقد ذكرنا عنه أنه قال: نهاني أَحمد أَن أَحدث عن فلان."],[145,"\"المناقب\" ص ١١٥"],[146,"الجزء: 15 - الصفحة: 425"],[147,"٩٩٤ - عبد الرحمن بن مهدي"],[148,"قال ابن الجوزي: أَخبرنا محمد بن أَبي منصور، قال: أَنا عبد القادر بن محمد، قال: أَنا إبراهيم بن عمر البَرْمَكي، قال: أَنا علي بن عبد العزيز بن مَرْدَك، قال: أَنا أَبو محمد بن أَبي حاتم، قال: ثنا أَحمد بن سنان الواسطي قال: سمعت عبد الرحمن بن مهدي يقول: كان أَحمد بن حنبل عندي. فقال: نظرنا فيما كان يخالفكم فيه وكيع أو فيما يخالف وكيع الناس، فإذا هي نيف وستون حرفًا."],[149,"\"المناقب\" ص ١١٥ - ١١٦"],[150,"٩٩٥ - محمد بن إدريس الشافعي"],[151,"قال ابن الجوزي: أَنبأَنا محمد بن أَبي طاهر البزاز، قال: أَنبأَنا أَحمد بن علي بن ثابت، قال: أَنا أَبو سعد إسماعيل بن علي بن الحسن بن بندار الإِستراباذي، قال: ثنا محمد بن عبد اللَّه الحافظ، قال: ثنا أَبو العباس محمد بن يعقوب، قال: أَنا الربيع، قال: أَنا الشافعي، قال: أَنا الثقة -وهو أَحمد ابن حنبل- عن عبد اللَّه بن الحارث، عن مالك بن أَنس، عن يزيد بن قسيط، عن سعيد بن المُسيَّب: أَن عمر وعثمان قضيا في المِلْطَاة بنصف دِيَةِ المُوضِحَة."],[152,"\"المناقب\" ص ١١٦"],[153,"قال ابن الجوزي: أَنبأَنا محمد بن عبد الملك بن خيرون، قال: أَنبأَنا أَحمد بن علي بن ثابت، قال: أَنا أَبو سعيد محمد بن موسى بن الفضل بن شاذان، قال: ثنا أَبو العباس محمد بن يعقوب الأصم، قال: أَنا الربيع بن"],[154,"الجزء: 15 - الصفحة: 426"],[155,"سليمان، قال: أَنا الشافعي، قال: ثنا الثقة من أصحابنا، عن يحيى بن سعيد القطان، عن شعبة بن الحجاج، عن قيس بن مسلم، عن طارق بن شهاب، أَن عمر بن الخطاب قال: إِنما الغنيمة لمن شهد الوقعة. قال الخطيب: قال لي أَبو الفضل علي بن الحسين الفَلَكي الحافظ: الرجل الذي لم يسمه الشافعي هو أَحمد بن حنبل."],[156,"\"المناقب\" ص ١١٦"],[157,"٩٩٦ - معروف الكرخي"],[158,"قال ابن الجوزي: أَنبأَنا يحيى بن الحسن بن البنا، قال: أَنبأَنا أَبو يعلى محمد بن الحسين، عن أَبي الفرج محمد بن فارس الغُورِيّ، قال: ثنا أَحمد بن المنادي، قال: ثنا أَبو بكر عمر بن إبراهيم، قال: ثنا يحيى بن أَكثم القاضي، قال: سمعت معروفًا -وذكر عنده أَحمد بن حنبل- قال: رأَيت أَحمد بن حنبل فتى عليه آثار النسك، فسمعته يقول كلامًا جمع فيه الخير سمعته يقول: من علم أنه إذا مات نسي، أحسن ولم يسئ."],[159,"\"المناقب\" ص ١١٧"],[160,"٩٩٧ - أسود بن عامر المعروف بـ (شاذان)"],[161,"قال ابن الجوزي: أَنبأَنا يحيى بن علي المُدِير، قال: أَنبأَنا أَبو بكر أَحمد بن علي الحافظ، قال: أَخبرني أَبو القاسم الأَزهري، قال: ثنا علي بن عمر الحافظ، قال: ثنا محمد بن مخلد، قال: ثنا أَبو بكر المَروذِي، قال: حدثني عبد الصمد بن يحيى، قال: سمعت شاذان"],[162,"الجزء: 15 - الصفحة: 427"],[163,"يقول: أَرسلت إلى أَبي عبد اللَّه -يعني: أَحمد بن حنبل- أَستأذنه أَن أُحَدِّث بحديث حماد عن قَتَادَة، عن عِكْرِمة، عن ابن عباس، عن النبي -صلى الله عليه وآله وسلم- \"رأيت ربي عز وجل\" (١) فقال: قل له قد حَدَّثَ به العلماء، حَدِّثْ به."],[164,"\"المناقب\" ص ١١٧"],[165,"٩٩٨ - الحسن بن موسى الأشيب"],[166,"قال ابن الجوزي: أَنبأَنا أَحمد بن عبد الملك بن خيرون، قال: أَنبأَنا أَحمد بن علي الحافظ، قال: أَخبرني عبيد اللَّه بن أَبي الفتح الفارسي، قال: ثنا علي بن عمر الحافظ، قال: ثنا القاضي بن الحسين بن إسماعيل، قال: ثنا الفضل بن سهل الأَعرج، قال: ثنا الحسن الأشيب، قال: ثنا شيبان، عن ليث، عن عطاء، عن عائشة قالت: أَفْطَرَ الحاجمُ والمَحْجُومُ (٢)."],[167,"(١) رواه الإمام أحمد ١/ ٢٨٥، وابن أبي عاصم في \"السنة\" (٤٤٠)، وصححه الألباني في \"ظلال الجنة\". قلت: وقد صح الحديث موقوفًا أيضًا، فقد روى البخاري (٤٧١٦) بإسناده، عن ابن عباس -رضي الله عنهما- في قوله تعالى: ﴿وَمَا جَعَلْنَا الرُّؤْيَا الَّتِي أَرَيْنَاكَ إِلَّا فِتْنَةً لِلنَّاسِ وَالشَّجَرَةَ الْمَلْعُونَةَ﴾، وقال: نص رؤيا عين، أريها رسول اللَّه -صلى الله عليه وآله وسلم- ليلة أسرى به. ﴿وَالشَّجَرَةَ الْمَلْعُونَةَ﴾ شجرة الزقوم. أهـ. (٢) روى ابن أبي شيبة ٢/ ٣٠٨ (٩٣١٠)، والنسائي في \"الكبرى\" ٢/ ٢٢٨ (٣١٩٢)، هكذا موقوفًا. ورواه مرفوعًا الإمام أحمد ٦/ ١٥٧، والنسائي في \"الكبرى\" ٢/ ٢٢٨ (٣١٩١)، وغيرهما. وله شاهد من حديث ثوبان -رضي الله عنه-، رواه الإمام أحمد ٥/ ٢٧٧، وأبو داود (٢٣٦٧)، وابن ماجه (١٦٨٠) وصححه الألباني في \"صحيح ابن ماجه\" (١٣٦٢)، و\"الإرواء\" (٩٣١)."],[168,"الجزء: 15 - الصفحة: 428"],[169,"قال الحسن الأشيب: وحدثني أَحمد بن حنبل، عن هاشم أَبي النضر، عن شيبان، عن النبي -صلى الله عليه وآله وسلم- بهذا."],[170,"\"المناقب\" ص ١١٧ - ١١٨"],[171,"٩٩٩ - داود بن عمرو الضبي"],[172,"قال ابن الجوزي: أَنبأَنا يحيى بن علي المُدِير، قال: أَنبأَنا أَحمد بن علي الحافظ، قال: أَنا أَبو الفتح عبد الملك بن عمر بن خلف البزار، قال: أَنا علي بن عمر الحافظ، قال: ثنا محمد بن مخلد، قال: ثنا محمد بن علي بن معدان، قال: سمعت داود بن عمر، يقول: سمعت أَحمد بن حنبل يقول: سمعت سفيان بن عُيَيْنَة يقول: وأَنعما. قال: وأهلا. قلت: الإشارة إلى الحديث المعروف \"وإن أبا بكر وعمر منهم وأَنْعمَا\" (١)."],[173,"\"المناقب\" ص ١١٨"],[174,"١٠٠٠ - أبو زكريا يحيى بن عبد الحميد الحماني"],[175,"قال ابن الجوزي: أَنبأَنا محمد بن عبد الملك قال: أَنبأَنا أَحمد بن علي بن ثابت، قال: قرأت على محمد بن أَحمد بن يعقوب المعدل، عن محمد بن عبد اللَّه بن نعيم النيسابوري قال: ثنا أَبو سعيد أَحمد بن سليمان بن نوح قال: ثنا البُوشَنْجيّ محمد بن إبراهيم قال: ثنا الحِمَّاني قال: ثنا أَحمد بن حنبل قال: ثنا إسحاق الأَزرق، عن شَرِيكٍ، عن"],[176,"(١) رواه الإمام أحمد ٣/ ٧٢، وأبو داود (٣٩٨٧)، والترمذي (٣٦٥٨)، وابن ماجه (٩٦). وصححه الألباني في \"صحيح ابن ماجة\" (٧٩)."],[177,"الجزء: 15 - الصفحة: 429"],[178,"بَيَانِ، عن قَيْسِ بن أَبي حازِمٍ، عن المُغِيرَةِ بن شُعْبَةَ، قال: كنا نصلي مع رسول اللَّه -صلى الله عليه وآله وسلم- الظهر بالهاجرة، فقال لنا: \"أَبردوا بالصلاة فإن شدة الحر من فَيْحِ جهنم\" (١)."],[179,"\"المناقب\" ص ١١٨ - ١١٩"],[180,"١٠٠١ - خلف بن هشام البزار"],[181,"قال ابن الجوزي: أَنبأَنا محمد بن أَبي طاهر البزار، قال: أَنبأَنا أَحمد بن علي الحافظ، قال: أَنبأَنا أَبو الحسن محمد بن رزق، قال: حدثني أَبو بكر محمد بن إسحاق المقرئ، قال: حدثني أَبو العباس أَحمد بن محمد بن يزيد البراثي، قال: سمعت خلفًا البزار يقول: سأَلت أَحمد بن حنبل أيُّ الأسانيد أثبت؟"],[182,"قال: أَيوب، عن نافع، عن ابن عمر، وإِن كان من حديث حماد بن زيد فيا لك! !"],[183,"\"المناقب\" ص ١١٩"],[184,"(١) رواه الإمام أحمد ٤/ ٢٥٠، وابن ماجة (٦٨٠)، والبيهقي ١/ ٤٣٩. قال البيهقي في \"السنن\" -عقبه: قال أبو عيسى الترمذي- فيما بلغني عنه: سألت محمدًا -يعني: البخاري- عن هذا الحديث فعدَّه محفوظًا، وقال: رواه غير شريك عن بيان عن قيس عن المغيرة. اهـ، مختصرًا. وقال البوصيري في \"الزوائد\" (٢٢٨): وإسناده صحيح، ورجاله ثقات. اهـ، مختصرًا. وله شاهد صحيح من حديث أبي هريرة عند الإمام أحمد ٢/ ٢٢٩، والبخاري (٥٣٦)، ومسلم (٦١٥)."],[185,"الجزء: 15 - الصفحة: 430"],[186,"١٠٠٢ - قتيبة بن سعيد"],[187,"قال ابن الجوزي: أَنبأَنا محمد بن أَبي منصور، قال: أَنا محمد بن علي بن ميمون، قال: أَنا محمد بن علي بن عبد الرحمن الحسني، قال: ثنا محمد بن علي بن عبد اللَّه الهمذاني، قال: ثنا محمد بن عمار العطار، قال: ثنا عبيد اللَّه بن أَحمد المروزي، قال: ثنا عبدان بن محمد، قال: ثنا قتيبة، قال: ثنا أَحمد بن حنبل، قال: ثنا محمد بن سلمة، عن محمد بن إسحاق، عن عبيد اللَّه بن طلحة، عن الحسن، عن عثمان بن أَبي العاصي: أَنه دُعِيَ إلى خِتان فأَبَى. وقال: كنا على عهد رسول اللَّه لا نأتي الخِتَانَ ولا نُدْعَى إِليه (١)."],[188,"\"المناقب\" ص ١١٩"],[189,"١٠٠٣ - علي بن المديني"],[190,"قال ابن الجوزي: أَخبرنا يحيى بن ثابت بن بُنْدار، قال: أَنا أَبي، قال: أَنا أَبو بكر البَرْقاني، قال: أَنا أَحمد بن إبراهيم الإسماعيلي، قال: ثنا ابن عبد الكريم الوراق، قال: ثنا الحسن بن علي الأزدي، قال: ثنا علي بن المديني، قال: حدثني أَحمد بن حنبل، قال: ثنا علي بن عياش الحمصي، قال: ثنا شعيب بن أَبي حمزة، عن محمد بن المنكدر، عن جابر قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"من قال حين يسمع"],[191,"(١) رواه الإمام أحمد ٤/ ٢١٧، والطبراني ٩/ ٥٧ (٨٣٨١). قال الهيثمي في \"مجمع الزوائد\" ٤/ ٢١٧: رواه أحمد والطبراني، وفيه محمد بن إسحاق وهو ثقة لكنه مدلس، اهـ."],[192,"الجزء: 15 - الصفحة: 431"],[193,"النداء: اللهم ربَّ هذِه الدعوِة التامة والصلاة القائمة، آتِ محمدًا الوسيلةَ والفضيلةَ، وابعثه مقامًا محمودًا الذي وعدتَه، حَلَّتْ له الشفاعة\" (١)."],[194,"\"المناقب\" ص ١٢٠"],[195,"قال ابن الجوزي: أَخبرنا عبد الملك بن أَبي القاسم، قال: أَنا عبد اللَّه ابن محمد الأَنصاري، قال: ثنا محمد بن أَحمد الجارودي، قال: سمعت محمد بن مالك السعدي، قال: سمعت صَعْصَعَة بن الحسين الرقي، قال: سمعت أبا شعيب الحراني، يقول: سمعت علي بن المديني، يقول: قال لي سيدي أَحمد بن حنبل: لا تحدث إلَّا من كتاب."],[196,"\"المناقب\" ص ١٢٠"],[197,"صَعْصعَة بن الحسين الرقي قال: سمعت أبا شعيب الحراني يقول: سمعت علي بن المديني يقول: قال لي سيدي أَحمد بن حنبل: لا تحدث إلَّا من كتاب."],[198,"\"المناقب\" ص ١٢٠"],[199,"قال ابن الجوزي: أَخبرنا عبد الملك بن أَبي القاسم، قال: أَنا عبد اللَّه بن محمد الأَنصاري، قال: أَنا أَبو يعقوب، قال: أَنا أبو بكر بن أَبي الفضل، قال: أَنا أَبو إسحاق البزاز، قال: ثنا عثمان بن سعيد الدَّارِمي، قال: سمعت علي بن المديني يقول: صح في \"أَفطر الحاجم والمحجوم\" حديث شداد وثوبان (٢). وأَقول: أَفطر الحاجم والمحجوم."],[200,"(١) رواه الإمام أحمد ٣/ ٣٥٤، والبخاري (٦١٤). (٢) حديث ثوبان: رواه الإمام أحمد ٢/ ٢٧٧، وأبو داود (٢٣٦٧)، وابن ماجة (١٦٨٠). وأما حديث شداد: فقد رواه الإمام أحمد ٤/ ١٢٢، وأبو داود (٢٣٦٩)، والنسائي في \"الكبرى\" ٢/ ٢٢٠ (٣١٤٩)، وابن ماجة (١٦٨١). ="],[201,"الجزء: 15 - الصفحة: 432"],[202,"قيل: فما عليه؟ قال: يقول أَبو عبد اللَّه -يعني: أَحمد بن حنبل: عليه قضاء يوم."],[203,"قال عثمان: وسمعت أَحمد يقول: عليه قضاء يوم قد صح عندنا فيه حديث ثوبان وشداد."],[204,"\"المناقب\" ص ١٢٠ - ١٢١"],[205,"١٠٠٤ - الحارث بن سريج النقال"],[206,"قال ابن الجوزي: أَنبأَنا ابن خيرون، قال: أَنبأَنا أَبو بكر أَحمد بن علي ابن ثابت، قال: أَنبأَنا أَبو طاهر محمد بن الحسين بن سعدون المَوْصِلي، قال: أَنا علي بن عمر الحوضي، قال: ثنا أَحمد بن الحسين بن عبد الجبار الصوفي، قال: ثنا الحارث بن سُرَيْج، قال: ثنا أَحمد بن محمد بن حنبل، قال: أخبرني صاحب لي -قد سماه- قال: كنت عند ابن المبارك وهو بالرقة مريض فدخل عليه أَبو المليح يَعُوده. فقال له: يا أبا عبد الرحمن، إني دخلت أَنا وصالح بن مسمار على مريض نعوده، فسمعت صالحًا يقول: يا هذا، إن ربك يستعتبك فأعتبه."],[207,"\"المناقب\" ص ١٢١"],[208,"= قال المنذري في \"مختصر سنن أبي داود\" ٣/ ٢٤٤ (٢٢٦٧): وقال إسحاق: حديث شداد إسناده صحيح، تقوم به الحجة، وقال أحمد: أحاديث \"أفطر الحاجم والمحجوم\"، \"ولا نكاح إلَّا بولي\" يشد بعضها بعضًا، وأنا أذهب إليها. اهـ. وقال ابن القيم في \"التهذيب\": وقال علي بن المديني في حديث شداد: لا أرى الحديثين إلَّا صحيحين. وقال عثمان بن سعيد الدارمي: صح عندي حديث \"أفطر الحاجم والمحجوم\" من حديث ثوبان وشداد بن أوس، وأقول به، وسمعت أحمد بن حنبل يقول به، وذكر أنه صح عنده حديث ثوبان وشداد. وقال الترمذي في \"العلل\" ١/ ٣٦٢: سألت البخاري؟ فقال: ليس في الباب شيء أصح من حديث شداد بن أوس. اهـ، مختصرًا."],[209,"الجزء: 15 - الصفحة: 433"],[210,"١٠٠٥ - أبو جعفر محمد بن الحسين البرجلاني"],[211,"قال ابن الجوزي: أَنبأَنا يحيى بن علي المُدِير، قال: أَنبأَنا أَحمد بن علي بن ثابت، قال: أَنا أَبو الحسين بن بِشْران، قال: أَنا أَبو علي الحسين بن صفوان، قال: ثنا أَبو بكر بن أَبي الدنيا، قال: ثنا محمد بن الحسين، قال: ثنا أَحمد بن حنبل، قال: ثنا إبراهيم بن خالد، قال: ثنا رباح بن زيد. أن النبي -صلى الله عليه وآله وسلم- قال لجبريل: \"لم تأتني إلَّا وأَنت صارٌّ بين عينيك\"؟ قال: إِني لم أضحك منذ خُلِقَت النار (١)."],[212,"\"المناقب\" ص ١٢١"],[213,"١٠٠٦ - محمد بن يحيى بن أبي سمينة"],[214,"قال ابن الجوزي: أَنبأَنا أَبو بكر بن أَبي طاهر البزاز، قال: أَنبأَنا أَبو محمد الحسن بن علي الجوهري، قال: أَنا أَبو حفص عمر بن محمد بن علي الناقد، قال: ثنا محمد بن علي الحفار، قال: ثنا محمد بن يحيى بن أَبي سمينة، قال: ثنا أَحمد بن حنبل، قال: ثنا الوليد عن زيد بن واقد، عن نافع أن عمر كان إذا رأى من لا يرفع يديه في الصلاة حصبه."],[215,"\"المناقب\" ص ١٢٢"],[216,"(١) رواه الإمام أحمد في \"الزهد\" ص ٣٦."],[217,"الجزء: 15 - الصفحة: 434"],[218,"١٠٠٧ - عبد الله بن عمرو بن محمد بن أبان القرشي الكوفي"],[219,"قال ابن الجوزي: أَنبأَنا محمد بن عبد الملك قال: أَنبأَنا أَبو بكر بن ثابت قال: أَنا أَبو الحسن محمد بن عمر بن عيسى البلدي قال: ثنا الحسن بن سعيد بن الفضل الأَدَميّ قال: ثنا أَحمد بن يحيى بن المهنأ قال: ثنا عبد اللَّه بن عمر بن أَبان قال: ثنا أَحمد بن حنبل قال: ثنا عامر بن صالح بن عبد اللَّه بن عروة بن الزبير قال: ثنا هشام بن عروة، عن أبيه، عن عائشة، عن النبي -صلى الله عليه وآله وسلم-: أَنه أمر ببناء المساجد في الدور وأَمر بها أن تنظف وتُطَيَّب (١)."],[220,"\"المناقب\" ص ١٢٢"],[221,"١٠٠٨ - محمد بن المصفى"],[222,"قال ابن الجوزي: أَخبرنا عبد اللَّه بن علي المقرئ قال: أَنا عبد الملك بن أَحمد قال: أَنا عبد العزيز بن علي بن أَحمد، قال: أَنا ابن مَرْدَك قال: ثنا ابن أَبي حاتم قال: ثنا أَبي قال: ثنا محمد بن مُصَفَّى قال: ثنا أَحمد بن حنبل قال: ثنا روح بن عبادة، عن شعبة، عن سيار، عن الشعبي، عن أَبي هريرة، عن النبي -صلى الله عليه وآله وسلم-: \"لا تناجشوا ولا تصروا الإبل والبقر\" (٢)."],[223,"\"المناقب\" ص ١٢٢ - ١٢٣"],[224,"(١) رواه الإمام أحمد ٦/ ٢٧٩، وأبو داود (٤٥٥)، والترمذي (٥٩٤)، وابن ماجة (٧٥٩). وصححه الألباني في \"صحيح أبي داود\" (٤٨٠). (٢) رواه الإمام أحمد ٢/ ٤١٠، والبخاري (٢١٤٨) ومسلم (١٥١٥)، بذكر \"الغنم\" بدلًا من \"البقر\"."],[225,"الجزء: 15 - الصفحة: 435"],[226,"١٠٠٩ - أحمد بن أبي الحواري"],[227,"قال ابن الجوزي: أَخبرنا محمد بن أَبي منصور، قال: أَنا عبد القادر بن محمد، قال: أَنا إبراهيم بن عمر، قال: أَنا ابن مَرْدَك، قال: ثنا محمد بن أَبي حاتم، قال: ثنا أَبي، قال: ثنا ابن أبي الحواري، قال: أَشهد على أَحمد بن حنبل أَنه قال: الثبت عندنا بالعراق وكيع ويحيى بن سعيد."],[228,"\"المناقب\" ص ١٢٣"],[229,"قال ابن الجوزي: أَنبأَنا ابن خيرون، قال: أَنبأَنا أَحمد بن علي الحافظ، قال: كتب إلى عبد الرحمن بن عثمان الدمشقي. وحدثنا عبد العزيز بن أَبي طاهر عنه قال: أَنا أَبو الميمون البجلي، قال: ثنا أَبو زُرْعَة، قال: حدثني أَحمد بن أَبي الحواري، قال: قال لي أَحمد بن حنبل: متى مولدك؟ قلت: سنة أَربع وستين. قال: وهي مولدي."],[230,"\"المناقب\" ص ١٢٣"],[231,"١٠١٠ - عبد الرحمن بن إبراهيم الدمشقي، المعروف بـ (دحيم)"],[232,"قال ابن الجوزي: أَنبأَنا محمد بن عبد الملك قال: أَنبأَنا أَحمد بن علي بن ثابت قال: كتب إليّ أَبو محمد عبد الرحمن بن عثمان بن القاسم الدمشقي. وحدثني عنه عبد العزيز بن أَبي طاهر الصوفي قال: أَنا أَبو الميمون عبد الرحمن بن عبد اللَّه بن عمر بن راشد البجلي، قال: ثنا أَبو زُرْعَة عبد الرحمن بن عمرو النَّصْرى قال: حدثني عبد الرحمن بن إبراهيم، عن أَحمد بن حنبل قال: لما مات الحسن جلس قتادة بعده،"],[233,"الجزء: 15 - الصفحة: 436"],[234,"فأَقام ثمان سنين فمات سنة ثمان عشرة ومائة، ثم جلس بعده مَطَر، ثم جلس بعده سعيد بن أَبي عَرُوبَة، قلت لعبد الرحمن: أَحمد حكاه لك؟ قال: نعم."],[235,"\"المناقب\" ص ١٢٣ - ١٢٤"],[236,"قال ابن الجوزي: وقد روى يحيى بن مَعِين أيضا عن أَحمد بن حنبل. وروى عنه أَبو بكر بن أَبي الدنيا. وروى البخاري عن رجل عنه. وقد أَخبرنا ابن أَبي منصور قال: أَنا عبد القادر بن محمد قال: ثنا إبراهيم بن عمر قال: ثنا ابن مَرْدَك قال: أَنا أَبو محمد بن أَبي حاتم قال: سمعت أَبي يقول: رأَيت في كتب إبراهيم بن موسى إلى أَحمد بن حنبل يسأَله عن مسأَلة."],[237,"\"المناقب\" ص ١٢٤"],[238,"الجزء: 15 - الصفحة: 437"],[239,"باب ما جاء في الجرح والتعديل"],[240,"١٠١١ - جواز الجرح"],[241,"قال أبو داود: سمعت أحمد، وعثمان بن أبي شيبة، والحسن بن علي، وهذا لفظه، كلهم يذكره عن عفان، عن يحيى بن سعيد قال: سألت سفيان الثوري، وسفيان بن عيينة، ومالك بن أنس، وشعبة بن الحجاج، عن الرجل يغلط في الحديث أو يكذب فيه؟ قالوا: بيِّن أمره، بيِّن أمره."],[242,"\"سؤالات أبي داود\" (١٣٤)"],[243,"قال صالح: حدثنا أبي، قال: حدثنا عفان، قال: حدثنا يحيى بن سعيد، قال: سألت شعبة وسفيان بن سعيد وسفيان بن عيينة ومالك بن أنس عن الرجل الذي لا يحفظ، أو يتهم في الحديث قالوا جميعًا: بيَّن أمره."],[244,"\"العلل\" رواية المروذي وغيره (٣١١)"],[245,"وقال عبد اللَّه: حدثني أبي، قال: حدثنا عفان، قال: حدثنا يحيى بن سعيد، قال: سألت شعبة وسفيان بن سعيد وسفيان بن عيينة ومالك بن أنس عن الرجل لا يحفظ أو يتهم في الحديث، فقالوا لي جميعا: بيَّن أمره."],[246,"\"العلل\" رواية عبد اللَّه (٤٦٨٤)"],[247,"قال أحمد بن مروان المالكي: ثنا عبد اللَّه بن أحمد بن حنبل، قال: جاء أبو تراب النخشبي إلى أبي، فجعل أبي يقول: فلان ضعيف وفلان ئقة، قال أبو تراب: يا شيخ لا تغتب العلماء."],[248,"قال: فالتفت أبي إليه قال: ويحك! هذا نصيحة، ليس هذا غيبة."],[249,"الجزء: 15 - الصفحة: 438"],[250,"وقال محمد بن بندار السباك الجرجاني: قلت لأحمد بن حنبل: إنه ليشتد عليّ أن أقول: فلان ضعيف فلان كذاب."],[251,"قال أحمد: إذا سكتَّ أنت وسكتُّ أنا فمتى يعرف الجاهل الصحيح من السقيم؟ !"],[252,"وقال إسماعيل الخطبي: ثنا عبد اللَّه بن أحمد، قلت لأبي: ما يقول في أصحاب الحديث يأتون الشيخ لعله أن يكون مرجئًا أو شيعيًا أو فيه شيء من خلاف السنة، أيسعني أن اسكت عنه أم أحذر عنه؟"],[253,"فقال أبي: إن كان يدعو إلى بدعة وهو إمام فيها ويدعو إليها، قال: نعم تحذر عنه."],[254,"\"شرح علل الترمذي\" لابن رجب ١/ ٤٦"],[255,"قال الحسن بن علي بن الحسن الإسكافي: سألت أبا عبد اللَّه عن معنى الغيبة؟"],[256,"قال: إذا لم ترد عيب الرجل."],[257,"قلت: فالرجل يقول: فلان لا يسمع، وفلان يخطئ، قال: لو ترك الناس هذا لم يعرف الصحيح من غيره."],[258,"\"المسودة\" ١/ ٥٥٦، \"شرح علل الترمذي\" لابن رجب ١/ ٤٧"],[259,"١٠١٢ - ما جاء في أن الصحابة كلهم عدول"],[260,"قال الأثرم: قلت لأبي عبد اللَّه أحمد بن حنبل: إذا قال رجل من التابعين: حدثني رجل من أصحاب النبي -صلى الله عليه وآله وسلم-، ولم يسمه فالحديث صحيح؟ قال: نعم."],[261,"\"التمهيد\" لابن عبد البر ١٦/ ٤٧٧"],[262,"الجزء: 15 - الصفحة: 439"],[263,"١٠١٣ - حد الصحبة"],[264,"قال إسحاق بن منصور: قُلْتُ لأحمد: هل للصحبةِ حدُّ تحدده؟"],[265,"قَالَ: لا، ومَن صحبَ النبي -صلى الله عليه وآله وسلم- ولو ساعة، فهو مِن أصحابِ رسول اللَّه -صلى الله عليه وآله وسلم-."],[266,"قال إسحاق: كمَا قَالَ."],[267,"\"مسائل الكوسج\" (٣٢٨٢)."],[268,"قال في رواية عبدوس بن مالك العطار: أفضل الناس بعد أهل بدر القرن الذي بعث فيهم، كل من صحبه سنة أو شهرًا أو يومًا أو ساعة أو رآه، فهو من أصحابه، له من الصحبة على قدر ما صحبه."],[269,"\"العدة\" ٣/ ٩٨٧، \"المسودة\" ١/ ٥٧٥ - ٥٧٦."],[270,"الجزء: 15 - الصفحة: 440"],[271,"فصل: ما جاء في شروط الجرح والتعديل"],[272,"١٠١٤ - لا يقبل الجرح إلا مفسرا"],[273,"سأل المروذي يحيى بن معين عن الصائم يحتجم، فقال: لا شيء عليه، ليس يثبت فيها خبر. فقال أبو عبد اللَّه: هذا كلام مجازفة."],[274,"وقال مهنا لأحمد: حديث خديجة: كان أبوها ما يرغب أن يزوجه (١)، فقال أحمد رحمه الله: الحديث معروف سمعته من غير واحد."],[275,"قلت: إن الناس ينكرون هذا. قال: ليس هو منكر."],[276,"ونقل عنه المروذي: قرئ على أبي عبد اللَّه رحمه الله: حديث عائشة كانت تلبى: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك (٢)."],[277,"(١) رواه الإمام أحمد ١/ ٣١٢، والطبراني ١٨/ ١٨٦ (١٢٨٣٨، ١٢٨٣٩)، ٢٢/ ٤٤٤ (١٠٨٥)، والبيهقي ٧/ ١٢٩ من حديث ابن عباس -رضي الله عنهما-. قال الهيثمي في \"المجمع\" ٩/ ٢٢٠: رواه أحمد والطبراني، ورجاله رجال الصحيح، اهـ. وفي الباب عن عمار بن ياسر، رواه البزار ٤/ ٢٤٨ (١٤١٨)، والبيهقي ٧/ ١٢٩. قال الهيثمي في \"المجمع\": رواه البزار، وفيه: عمر بن أبي بكر المؤملي، وهو متروك. قلت: قد روى ابن سعد ١/ ١٣٢ بإسناده إلى عائشة، وابن عباس أن أبا خديجة -خويلد بن أسد- مات قبل حرب الفجار، وإنما زوجها عمها عمر بن أسد. ثم روى نحو ما رواه أحمد والطبراني، وغيرهما فيما سبق تخريجه، ثم قال وقال محمد بن عمر: فهذا كله عذرنا غلط ووهل، والمثبت عندنا المحفوظ عن أهل العلم أن أباها خويلد بن أسد مات قبل الفجار، وأن عمها عمرو بن أسد زوجها رسول اللَّه -صلى الله عليه وآله وسلم-. اهـ. (٢) رواه الإمام أحمد ٦/ ٣٢، والبخاري (١٥٥٠)."],[278,"الجزء: 15 - الصفحة: 441"],[279,"فقال أبو عبد اللَّه: كان فيه والملك لا شريك لك فتركته؛ لأن الناس خالفونا."],[280,"\"العدة\" ٣/ ٩٣١ - ٩٣٣، \"المسودة\" ١/ ٥٣٤ - ٥٣٥"],[281,"١٠١٥ - هل يقبل الجرح والتعديل من الواحد؟"],[282,"؟"],[283,"قال في رواية الأثرم: إذا روى الحديث عبد الرحمن بن مهدي عن رجل، فهو حجة."],[284,"ونقل أبو زرعة قال: سمعت أحمد بن حنبل رحمه الله يقول: مالك بن أنس إذا روى عن رجل لا يعرف فهو حجة."],[285,"ونقل إسماعيل بن سعيد قال: قلت لأحمد: تعديل الرجل الواحد إذا كان مشهورًا بالصلاح؟ قال: يقبل ذلك."],[286,"\"العدة\" ٣/ ٩٣٤ - ٩٣٥، \"المسودة\" ١/ ٥٣٧ - ٥٣٨"],[287,"١٠١٦ - قواعد في الأساليب والعلل"],[288,"قال الميموني: حدثنا أحمد قال: حدثنا عبد الصمد قال: حدثنا حرب قال: قال يحيى: كل شيء عن أبي سلام، فإنما هو كتاب."],[289,"\"العلل\" رواية المروذى وغيره (٣٤٤)"],[290,"قال ابن أبي خيثمة: حدثنا أحمد بن حنبل قال: نا عبد الصمد بن عبد الوارث، عن حرب بن شداد قال: قال لي يحيى بن أبي كثير: كل شيء عن أبي سلام -وأبو سلام اسمه ممطور الحبشي- فإنما هو كتاب."],[291,"\"تاريخ ابن أبى خيثمة\" (١٢٦٠)"],[292,"قال ابن هانئ: سمعته يقول: آل كعب بن مالك كلهم ثقات، كل من"],[293,"الجزء: 15 - الصفحة: 442"],[294,"روي عنه الحديث [من أولاد كعب بن مالك وذريته فهو ثقة] (١)."],[295,"\"مسائل ابن هانئ\" (٢١٥٢)"],[296,"قال ابن هانئ: سمعته يقول: كل من كتب يتكل على الكتاب فيصحف."],[297,"\"مسائل ابن هانئ\" (٢٢٢٧)"],[298,"وقال ابن هانئ: سمعته يقول: ما في أصحاب شعبة أقل خطأ من محمد بن جعفر."],[299,"\"مسائل ابن هانئ\" (٢٢٧٦)"],[300,"وقال ابن هانئ: وسمعته يقول: ما روى مالك عن أحد إلَّا وهو ثقة، كل من روى عنه مالك، فهو ثقة."],[301,"\"مسائل ابن هانئ\" (٢٣٦٧)."],[302,"قال حرب: سمعت أحمد بن حنبل يقول: لم يكن أحد اسمه منصور أفضل من منصور بن زاذان."],[303,"\"مسائل حرب\" ص ٢٠١"],[304,"قال عبد اللَّه: قال أبي: لم يسمع وكيع من عبيد اللَّه بن عمر شيئًا."],[305,"\"العلل\" رواية عبد اللَّه (٤٤)."],[306,"وقال عبد اللَّه: حدثني أبي قال: وكيع لم يسمع من عثمان بن الأسود شيئًا."],[307,"\"العلل\" رواية عبد اللَّه (٢٨٠٢)"],[308,"قال عبد اللَّه: قال أبي: كلهم ثقات -يعني: من كنيته أبو حازم."],[309,"\"العلل\" رواية عبد اللَّه (٣٦٠٦)."],[310,"قال الفضل بن زياد: قال أحمد بن حنبل: ليس أحد أروى لحديث الشاميين من إسماعيل بن عياش والوليد بن مسلم."],[311,"\"المعرفة والتاريخ\" ٢/ ١٦٥، \"تاريخ بغداد\" ٦/ ٢٢٢ - ٢٢٣، \"تهذيب الكمال\" ٣١/ ٩٢"],[312,"قال حنبل: سمعت أبا عبد اللَّه يقول: أعلمنا بالرجال يحيى بن معين،"],[313,"(١) زيادة من \"شرح علل الترمذي\" ٢/ ٧٧٩."],[314,"الجزء: 15 - الصفحة: 443"],[315,"وأحفظنا للأبواب سليمان الشاذكوني، وعلي أحفظنا للطوال."],[316,"\"تاريخ بغداد\" ٩/ ٤١، \"تهذيب الكمال\" ٣١/ ٥٥٣، \"سير أعلام النبلاء\" ١١/ ٨٦، \"بحر الدم\" (١١٦١)"],[317,"وقال محمد بن رافع: سمعت أحمد بن حنبل يقول: كل حديث لا يعرفه يحيى بن معين فليس بحديث."],[318,"\"تاريخ بغداد\" ١٤/ ١٨٠، \"تهذيب الكمال\" ٣١/ ٥٥٣، \"سير أعلام النيلاء\" ١١/ ٧٩، \"بحر الدم\" (١١٦١)"],[319,"قال الميموني: سمعت أبا عبد اللَّه يقول: أخذ مالك كتاب مخرمة بن بكير فنظر فيه، فكل شيء يقول: بلغني عن سليمان بن يسار فهو من كتاب مخرمة."],[320,"\"تهذيب الكمال\" ٢٧/ ٣٢٦، \"بحر الدم\" (٩٦٨)"],[321,"وقال أبو حاتم الرازي: أشهد على أحمد بن حنبل أنه قال: الثبت عندنا بالعراق وكيع بن الجراح، ويحيى بن سعيد، وعبد الرحمن بن مهدي."],[322,"\"تهذيب الكمال\" ٣٠/ ٤٧٤، \"سير أعلام النبلاء\" ٩/ ١٥٢"],[323,"وقال أبو زرعة الدمشقي: سمعت أحمد بن حنبل يقول: الثبت بالعراق: يحيى، وعبد الرحمن، ووكيع."],[324,"قال: فذكرت ذلك ليحيى بن معين؛ فقال: الثبت بالعراق وكيع."],[325,"\"تهذيب الكمال\" ٣٠/ ٤٧٤"],[326,"وقال أبو زرعة الدمشقي: قال لي أحمد بن حنبل: كان عندكم ثلاثة أصحاب حديث مروان بن محمد والوليد وأبو مسهر."],[327,"\"تهذيب الكمال\" ٣١/ ٩٣"],[328,"قال ابن هانئ: قال أحمد: كل أبي فروة ثقة إلَّا أبا فروة الجزري -يعني: يزيد بن سنان."],[329,"\"شرح علل الترمذي\" ٢/ ٧٧٩"],[330,"الجزء: 15 - الصفحة: 444"],[331,"باب ما جاء في شروط قبول خبر الراوي"],[332,"أولا: أن يكون عدلا"],[333,"١٠١٧ - بم تثبت العدالة؟"],[334,"؟"],[335,"قال أحمد في رواية الفضل بن زياد، وقد سأله عن أبي حميد يروي عن مشايخ لا يعرفهم، وأهل البلد يثنون عليهم؛ فقال: إذا أثنوا عليهم قبل ذلك منهم، هم أعرف بهم."],[336,"\"العدة\" ٣/ ٩٣٦، \"المسودة\" ١/ ٥٠٩"],[337,"١٠١٨ - هل يقبل خبر من لم تعرف عدالته؟"],[338,"؟"],[339,"قال ابن هانئ: وسمعت أبا عبد اللَّه يقول: كنا نحن نكتب عن كل من يقدم علينا."],[340,"\"مسائل ابن هانئ\" (٢١٠٨)"],[341,"١٠١٩ - هل رواية العدل عن غيره تعديلا لغيره؟"],[342,"؟"],[343,"وقال أبو داود: قلت لأحمد: إذا روى يحيى أو عبد الرحمن بن مهدي عن رجل مجهول، يحتج بحديثه؟ قال: يحتج بحديثه."],[344,"\"سؤالات أبي داود\" (١٣٧)"],[345,"قال الميموني: سمعت أحمد بن حنبل غير مرة يقول: كان مالك بن أنس من أثبت الناس في الحديث، ولا تبالي أن لا تسأل عن رجل روى عنه مالك بن أنس، ولاسيما مديني."],[346,"\"الجرح والتعديل\" ١/ ١٧، \"الكامل\" لابن عدي ١/ ١٧٧، \"السنن الكبرى\" للبيهقي ١٠/ ٢٧٩، \"شرح علل الترمذي\" لابن رجب ١/ ٨١"],[347,"الجزء: 15 - الصفحة: 445"],[348,"قال أبو زرعة الدمشقي: قال الإمام أحمد: مالك بن أنس إذا روى عن رجل لا يعرف فهو حجة."],[349,"\"العدة في أصول الفقه\" ٣/ ٩١٢، \"شرح علل الترمذي\" لابن رجب ١/ ٨٠"],[350,"١٠٢٠ - حكم الرواية عمن يأخذ الأجرة على الحديث"],[351,"قال سلمة بن شبيب: سألت أحمد، قلت: يا أبا عبد اللَّه، نكتب عن هؤلاء الذين يأخذون الدراهم ويحدثون؟"],[352,"قال: لا تكتب عنهم ولا كرامة."],[353,"\"العدة\" ٣/ ٩٥٤، \"طبقات الحنابلة\" ١/ ٤٥٠، \"المسودة\" ١/ ٥٢٨ - ٥٢٩"],[354,"قال خُشنام بن سعد: سألت أحمد، قلت: نكتب الحديث عمن يأخذ الدراهم على الحديث؟"],[355,"قال: لا تكتب عنه."],[356,"\"طبقات الحنابلة\" ١/ ٤٠٧ - ٤٠٨"],[357,"١٠٢١ - الرواية عن الكذابين"],[358,"قال إسحاق بن منصور: قُلْتُ لأبي عبد اللَّه: متى يتركُ حديث الرجل؟"],[359,"قال: إذا كان الغالب عليه الخطأ."],[360,"قُلْتُ: الكذب من قليلٍ أو كثير؟ قال: نعم."],[361,"\"مسائل الكوسج\" (٣٣٧٤)"],[362,"وقال في رواية إبراهيم وسندي في الرجل يعرف بالكذب في الشيء، يحدث به القوم، فليس نعرف منه الكذب في الرواية: كيف يؤمن هذا على الرواية أن يكذب فيها إذا عُرف منه الكذب في شيء؟ !"],[363,"\"العدة\" ٣/ ٩٢٥"],[364,"الجزء: 15 - الصفحة: 446"],[365,"قال أحمد في رواية علي بن سعيد في الرجل يكذب كذبةً واحدة: لا يكون في موضع العدالة، الكذب شديد."],[366,"\"العدة\" ٣/ ٩٢٧، \"التمهيد\" ٣/ ١١٠."],[367,"نقل أبو عبد الرحمن عبيد اللَّه بن أحمد الحلبي قال: سألت أحمد بن حنبل رحمه الله عن محدث كذب في حديث واحد، ثم تاب ورجع، قال: توبته فيما بينه وبين اللَّه تعالى، ولا يكتب عنه حديث أبدًا."],[368,"\"العدة\" ٣/ ٩٢٨، \"المسودة\" ١/ ٥١٩."],[369,"قال أحمد في رواية مهنا: من نوى أن يدغل في الحديث ولم يدغل سقط."],[370,"\"المسودة\" ١/ ٥٢٠."],[371,"نقل عنه سندي وغيره: إذا كان الراوي يتساهل في أحاديث الناس ويكذب فيها، ويتحرز في حديث رسول اللَّه -صلى الله عليه وآله وسلم-، لم تقبل روايته، وأنكر على من قبل روايته إنكارًا شديدًا."],[372,"\"المسودة\" ١/ ٥٢٩."],[373,"١٠٢٢ - حكم الرواية عن أهل الفسق والمعاصي"],[374,"قال صالح: قلت لأبي: ما تقول في رجل يبول قائمًا، ويمسح فرجه بيمينه، ويستقرض الدراهم ولا يرد، ويقول القول ويحلف، ويأمر بالمعروف ولا يأتيه، وينهي عن المنكر ويرتكب بعض ذلك، أحمل عنه العلم؟"],[375,"الجزء: 15 - الصفحة: 447"],[376,"فقال: أكره أن يمس الرجل فرجه بيمينه، والبول قائمًا لا بأس به، ويروى عن النبي -صلى الله عليه وآله وسلم- (١). وإذا مات ولم يقض دينه، ولم يقض عنه، ولم يوص بذلك، ولم يكفر عن يمينه؛ فليس هذا بعدل."],[377,"\"مسائل صالح\" (٥٦٢)."],[378,"قال أحمد في روإية أحمد بن الحسين: لا يكتب الحديث عمن يسكر."],[379,"\"العدة\" ٣/ ٩٢٥"],[380,"قال أحمد في رواية سندي الخواتيمي: لا يُعجبني أن يكتب الحديث عن معين -يعني: يبيع هذِه العينة."],[381,"\"العدة\" ٣/ ٩٥٣، \"المسودة\" ١/ ٥٢٨"],[382,"١٠٢٣ - هل المعصية تسقط العدالة؟"],[383,"؟"],[384,"قال أبو حاتم: حادثت أحمد بن حنبل فيمن شرب النبيذ من محقق أهل الكوفة، وسميت له عددًا منهم، فقال: هذِه زلات لهم، ولا تسقط عدالتهم بزلاتهم."],[385,"\"المسودة\" ١/ ٥٢٧."],[386,"(١) روى الإمام أحمد ٤/ ٣٨٣، والبخاري (١٥٣)، ومسلم (٢٦٧) من حديث أبي قتادة أن النبي -صلى الله عليه وآله وسلم- قال: \"لا يمسكن أحدكم ذكره بيمينه وهو يبول. . الحديث، وروى الإمام أحمد ٥/ ٤٠٢، والبخاري (٢٢٤)، ومسلم (٢٧٣) من حديث حذيفة أنه قال: كنت مع النبي -صلى الله عليه وآله وسلم- فانتهى إلى سباطة قوم فبال قائمًا. . الحديث."],[387,"الجزء: 15 - الصفحة: 448"],[388,"١٠٢٤ - حكم الرواية عن جند السلطان"],[389,"قال أحمد في رواية المروذي وقد سأله: يكتب عن الرجل إذا كان جنديًا، فقال: أما نحن فلا نكتب عنهم."],[390,"وقال أحمد في رواية إبراهيم بن الحارث: إذا كان الرجل في الجند لم أكتب عنه."],[391,"\"العدة\" ٣/ ٩٥٢، \"المسودة\" ١/ ٥٣٢."],[392,"١٠٢٥ - حكم الرواية عن أهل البدع"],[393,"قال إسحاق بن منصور: كان أبو عبد اللَّه يحدث عن المرجئ إذا لم يكن داعيًا."],[394,"\"مسائل الكوسج\" (٣٣٨٤)"],[395,"قال المروذي: وكان أبو عبد اللَّه يحدث عن المرجئ؛ إذا لم يكن داعية أو مخاصمًا."],[396,"\"العلل\" رواية المروذي وغيره (٢١٣)."],[397,"قال عبد اللَّه: قلت لأبي: ما تقول في أصحاب الحديث، يأتون الشيخ لعله يكون مرجئًا، أو شيعيًا، أو فيه شيء من خلاف السنة، أينبغي أن أسكت فلا أحذر عنه، أم أحذر عنه؟ قال: إن كان يدعو إلى بدعة، وهو إمام فيها ويدعو إليها، قال: نعم تحذر عنه."],[398,"\"مسائل عبد اللَّه\" (١٥٩١)."],[399,"قال عبد اللَّه: ذُكر عند أبي رجل من أهل البصرة ممن كان يحدث، فقلت: إنه واقفي (١) يقف، وقد ترك أصحاب الحديث ما يأتونه، فقال: أبعده اللَّه."],[400,"\"العلل\" رواية عبد اللَّه (١٤٤٢)"],[401,"(١) الواقفي هو من وقف في القرآن بالشك هل هو مخلوق أو غير مخلوق."],[402,"الجزء: 15 - الصفحة: 449"],[403,"قال أحمد في رواية الأثرم، وقد ذكر له أن فلانًا أمر بالكتب عن سعد العوفي، فاستعظم ذلك وقال: جهمي، ذاك امتحن فأجاب قبل أن يكون ترهيب."],[404,"\"العدة\" ٣/ ٩٤٨، \"المسودة\" ١/ ٥٢٦"],[405,"وقال أحمد بن سهل: سمعت الإمام أحمد في وصية وصاهم: وإياكم أن تكتبوا عن أحد من أهل الأهواء قليلًا ولا كثيرًا، عليكم بأصحاب الآثار والسنن."],[406,"وسُئل عن المرجئ نسمع منه الحديث؟ قال: نعم، إلَّا أن يكون داعية، مثل سلم بن سالم، رواه عنه محمد بن القاسم."],[407,"\"المسودة\" ١/ ٥٢٢."],[408,"قال أحمد في رواية أبي داود: احتملوا من المرجئة الحديث، ويكتب عن القدري إذا لم يكن داعية."],[409,"وقال المروذي: كان أبو عبد اللَّه يحدث عن المرجئ إذا لم يكن داعيًا."],[410,"\"شرح علل الترمذي\" لابن رجب ١/ ٥٥"],[411,"١٠٢٦ - حكم الرواية عمن أجاب في المحنة"],[412,"قال أبو زرعة: كان أحمد لا يرى الكتابة عن أبي نصر، ولا عن يحيي ابن معين، ولا أحد ممن امتحن فأجاب."],[413,"\"تاريخ بغداد\" ١٠/ ٤٢١، \"المناقب\" لابن الجوزى ص ٤٧٣ \"تهذيب الكمال\" ١٨/ ٣٥٦، ٣١/ ٥٥٣، \"بحر الدم\" (١١٦١)"],[414,"قال أحمد في رواية محمود بن غيلان: لا أحب أن أحدث عمن أجاب. يعني: في المحنة."],[415,"\"العدة\" ٣/ ٩٥٣، \"المسودة\" ١/ ٥١٥"],[416,"الجزء: 15 - الصفحة: 450"],[417,"قال حبيش بن سندي: قيل لأبي عبد اللَّه: هؤلاء الذين امتحنوا نكتب عنهم؟"],[418,"قال: أما أنا فلا أروي عن أحد منهم."],[419,"قيل له: أنه قد حُكي عنك أنك تأمر بالكتاب عن القواريري، فأنكر ذلك وقال: أنا أقول: لا أروي عن أحد منهم، فآمرُ بالكتاب عنهم؟ !"],[420,"\"طبقات الحنابلة\" ١/ ٣٩١."],[421,"وقال حجاج بن يوسف الثقفي بن الشاعر: قلت لأحمد: أكتب عمن أجاب في المحنة؟ فقال: أنا لا أكتب عنهم."],[422,"وقال عبد اللَّه بن أحمد: كان الحجاج بن الشاعر لا يحدث عمن أجاب."],[423,"\"طبقات الحنابلة\" ٧/ ٣٩٧."],[424,"١٠٢٧ - حكم الراوية عن أصحاب الرأي"],[425,"قال ابن هانئ: وسمعته يقول: تركنا أصحاب الرأي، وكان عندهم حديث كثير، فلم نكتب عنهم؛ لأنهم معاندون للحديث لا يفلح منهم أحد."],[426,"\"مسائل ابن هانئ\" (١٩٣٠)"],[427,"قال ابن هانئ: وسئل أحمد عن أبي حنيفة: يروى عنه؟"],[428,"قال: لا."],[429,"\"مسائل ابن هانئ\" (٢٣٦٨)."],[430,"قال ابن هانئ: قيل لأحمد: فأبو يوسف؟"],[431,"قال: كأنه أمثلهم."],[432,"ثم قال: كل من وضع الكتب فلا يعجبني، ويجرد الحديث."],[433,"\"مسائل ابن هانئ\" (٢٣٦٩)."],[434,"الجزء: 15 - الصفحة: 451"],[435,"قال عبد اللَّه: سمعت أبي يقول: أهل الرأي لا يروى عنهم الحديث."],[436,"\"العلل\" برواية عبد اللَّه (١٧٠٧)"],[437,"١٠٢٨ - التحديث عن بني إسرائيل"],[438,"قال صالح: قلت: قول النبي -صلى الله عليه وآله وسلم-: \"حدثوا عن بني إسرائيل ولا حرج\" (١) يحدث الرجل بكل شيء يريد؟"],[439,"قال أبي: يروى عن النبي -صلى الله عليه وآله وسلم- أنه قال: \"من حدث عني حديثا يرى أنه كاذب، فهو أحد الكذابين\" (٢) وقال -صلى الله عليه وآله وسلم-: \"حدثوا عن بني إسرائيل ولا حرج\"، ففرق بينهما: يحدث عنه وما يحدث عن بني إسرائيل، فقال: \"حدثوا عن بني إسرإِئيل ولا حرج؛ فإنه كانت فيهم الأعاجيب\" (٣)، فيكون الرجل يحدث عن بني إسرائيل وهو يرى أنه ليس كذلك؛ فلا بأس أن يحدث به، ولا يحدث عن النبي -صلى الله عليه وآله وسلم- إلَّا ما يرى أنه صدق."],[440,"\"مسائل صالح\" (٢٨٩)."],[441,"(١) رواه الإمام أحمد ٢/ ١٥٩، والبخاري (٣٤٦١) من حديث عبد اللَّه بن عمرو. (٢) رواه الإمام أحمد ٤/ ٢٥٢ من حديث المغيرة بن شعبة، ومسلم في المقدمة، باب وجوب الرواية عن الثقات وترك الكذابين، من حديث سمرة بن جندب والمغيرة بن شعبة. (٣) رواه الإمام أحمد في \"الزهد\" ص ٢٣، وابن أبي شيبة ٥/ ٣٩ (٢٦٤٧٧) وعبد بن حميد في \"المنتخب\" ٣/ ٨٢ (١١٥٤) من حديث جابر بن عبد اللَّه -رضي الله عنه-. وصححه الألباني في \"السلسلة الصحيحة\" (٢٩٢٦)."],[442,"الجزء: 15 - الصفحة: 452"],[443,"ثانيا: أن يكون ضابطا"],[444,"١٠٢٩ - الرواية عمن حدث ونسي"],[445,"ونقل حرب عنه: أنه سُئل عن حديث الولي، فقال: لا يصح؛ لأن الزهري سُئل عنه فأنكره (١)."],[446,"\"مسائل حرب\" ص ٤٦٣"],[447,"قال عبد اللَّه: سمعت أبي يقول: قال عفان: سمعت حمادًا يقول: عمير بن حبيب ليس فيه عن أبيه."],[448,"فقلت له: إنك حدثتني عن أبيه، عن جده، فقال: أحسب أنه عن أبيه عن جده (٢)."],[449,"\"السنة لعبد اللَّه\" (٦٢٥)"],[450,"(١) روى قصة نسيان الزهري: الإمام أحمد ٦/ ٤٧، والترمذي (١١٠٢)، ورواه أبو داود (٢٠٨٣)، (١١٠٢)، وابن ماجة (١٨٧٩) دون ذكر القصة. قال الترمذي: حديث حسن، وقال الحاكم في \"علوم الحديث\" ص ١٣٤: هذا حديث محفوظ من حديث ابن جريج، عن سليمان بن موسى الأشرق وقال في \"المستدرك\" ٢/ ١٦٨ - ١٦٩: هذا حديث صحيح على شرط البخاري ومسلم. وقال أبو حاتم ابن حبان في \"صحيحه\" ٩/ ٣٨٥ - ٣٨٦: هذا خبر أوهم من لم يحكم صناعة الحديث أنه منقطع، أو أصل به بحكاية حكاها ابن علية عن ابن جريج في عقب هذا الخبر، قال: ثم لقبت بمثله وذلك أن الخيِّر الفاضل المتقن الضابط من أهل العلم قد يحدث بالحديث، ثم ينساه، وإذا سئل عنه لم يعرف فليس بنسيانه الشيء الذي حدث به بدال على بطلان أصل الخبر، والمصطفى -صلى الله عليه وآله وسلم- صلى فسها. وقال ابن الجوزي في \"التحقيق\" ٢/ ٢٥٥ - ٢٥٦: هذا الحديث صحيح وقال عبد الحق في \"الأحكام الوسطى\" ٣/ ١٣٩: هذا الحديث أصح شيء في هذا الباب، كذا قال ابن معين. وقال ابن الملقن في \"البدر المنير\" ٧/ ٥٥٣: هذا الحديث صحيح. وكذلك صححه الألباني في \"الإرواء\" (١٨٤٠)، \"صحيح أبي داود\" (١٨١٧). (٢) رواه ابن أبي شيبة ٦/ ١٦٠ (٣٠٣١٨) وفي \"الإيمان\" (١٤) والخلال في \"السنة\" ="],[451,"الجزء: 15 - الصفحة: 453"],[452,"قال في رواية الأثرم: قلت لأبي عبد اللَّه: يضعف الحديث عندك بمثل هذا: إن حدث الرجل الثقة بالحديث عن الرجل، فيسأل عنه فينكره ولا يعرفه، فقال: لا، ما يضعف عندي بهذا."],[453,"فقلت: مثل حديث الولي، ومثل حديث اليمين مع الشاهد (١)، فقال: قد كان معمر يروي عن ابنه، عن نفسه، عن عبد اللَّه بن عمر."],[454,"ونقل الميموني عنه لما ذكر له حديث الزهري وما قاله، فقال: كان ابن عيينة يحدث بأشياء، ثم قال: ليس من حديثي ولا أعرفه، وقد يحدث الرجل، ثم ينسى."],[455,"ونقل أبو طالب عنه أنه قال: يجوز أن يكون الزهري حدث به ثم نسيه."],[456,"وقال أبو الجود: قلت لأبي عبد اللَّه: \"أيما امرأة زوجت بغير ولي\"؟"],[457,"فقال: لا أحسبه صحيحًا؛ لأن إسماعيل قال: قال ابن جريج: لقيت"],[458,"= ٢/ ٣١ - ٣٢، والأجري في \"الشريعة\" ص ٩٥ (٢٠٧) والبيهقي في \"الشعب\" ١/ ٧٧ (٥٦). (١) حديث الولي تقدم تخريجه، أما حديث اليمين مع الشاهد فرواه أبو داود (٣٦١٠) قال: حدثنا أحمد بن أبي بكر أبو مصعب الزهري: حدثنا الداروردي عن ربيعة بن أبي عبد الرحمن، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة أن النبي -صلى الله عليه وآله وسلم- قضى باليمين مع الشاهد. قال أبو داود: وزادنىِ الربيع بن سليمان المؤذن في هذا الحديث قال: أخبرني الشافعي عن عبد العزيز قال: فذكرت ذلك لسهيل فقال: أخبرني ربيعة وهو عندي ثقة أنبي حدثته إياه ولا أحفظه. قال عبد العزيز وقد كان أصابت سهيلًا علة أذهبت بعض عقله ونسى بعض حديثه فكان سهيل بعد يحدثه عن ربيعة عن أبيه. ورواه بدون القصة الترمذي (١٣٣٤٤)، وابن ماجة (٢٣٦٨)، وابن حبان ١١/ ٤٦٢ (٥٠٧٣) قال الترمذي: حديث حسن غريب. وصححه الألباني في \"الإرواء\" ٨/ ٣٠١."],[459,"الجزء: 15 - الصفحة: 454"],[460,"الزهري وسألته عنه فقال: لا أعرفه (١)."],[461,"\"العدة في أصول الفقه\" ٣/ ٩٦٠."],[462,"١٠٣٠ - إذا وجد سماعه في كتاب، ولم يذكر أنه سمعه، هل يجوز روايته؟"],[463,"؟"],[464,"قال عبد اللَّه: قال أبي: قال لي شعيب بن حرب: أعطني كتاب ابن عيينة عن الزهري، فأتيته بكتابي فجئت بعدُ آخذ الكتاب منه، فمر بحديث فقال: سفيان سمع هذا من الزهري، فسكتُّ أو قلت: لا أدري."],[465,"\"العلل\" رواية عبد اللَّه (٧٥٠)"],[466,"وقال عبد اللَّه: سمعت أبي يقول: ذهبت أنا وحامد البلخي إلى شعيب بن حرب بمكة، فقال: جيئوني بكتاب ابن عيينة عن الزهري، فجئته به فمكث أيامًا، ثم طلبناه منه فجئنا فمرض، فقال لنا: هذا الحديث سمعه ابن عيينة من الزهري؟ قلنا: لا ندري."],[467,"قال: ومات شعيب ونحن بمكة، دفناه بالليل. أو كما قال أبي، أظنه قال: كان به البطن."],[468,"\"العلل\" رواية عبد اللَّه (٥١٣٦)"],[469,"قال أحمد في رواية مهنا: إذا كان يحفظ الشيء، وفي الكتاب شيء فالكتاب أحب إليَّ."],[470,"وقال في رواية الحسين بن حسان في الرجل يكون له السماع مع الرجل: فلا بأس أن يأخذه بعد سنين، إذا عرف الخط."],[471,"ونقل الحسن بن محمد بن الحارث عنه: إذا عرف خطه فلا يشهد عليه"],[472,"(١) سبق تخريجه."],[473,"الجزء: 15 - الصفحة: 455"],[474,"إلَّا ما يحفظه، إلَّا أن يكون منسوخًا عنده في حرزه، فكأنه إذا كان عنده مكتوبًا في حرزه، شهد به، وإن لم يحفظه، ثم قال: كتاب العلم أيسر. يعني: يشهد عليه."],[475,"قيل له: إذا أعار كتاب العلم، فقال: لابد من أن يفعل ذلك، إذا أعاره من يثق به، قيل له: فإن لم يثق به: كل ذاك أرجو أن لا يحدث فيه، فإن الزيادة في الحديث ليس تكاد تخفى. وكأنه رأى ذلك أوسع من الشهادة."],[476,"\"العدة\" ٣/ ٩٧٤ - ٩٧٥، \"المسودة\" ١/ ٥٥٥، \"التمهيد\" ٣/ ١٦٩."],[477,"١٠٣١ - الراوي يخفى عليه بعض ما في كتابه، يروى عنه؟"],[478,"؟"],[479,"قال ابن هانئ: قلت لأبي عبد اللَّه: الكتاب قد طال على الإنسان عهده لا يعرف بعض حروفه، فيخبره بعض أصحابه، ما ترى في ذلك؟"],[480,"قال: إذا كان يعلم أنه كما في الكتاب فليس بذلك بأسٌ."],[481,"\"مسائل ابن هانئ\" (١٩٢٧)."],[482,"١٠٣٢ - الرواية عن الذي لا يحفظ إذا حدث من كتاب غيره"],[483,"وقال المروذي: سمعت أبا عبد اللَّه قال: ما بالكوفة مثل هنّاد بن السري هو شيخهم."],[484,"فقيل له: هو يحدث من كتاب ورّاقة؛ فجعل يسترجع، ثم قال: إن كان هكذا لم يكتب عن هنّاد شيء."],[485,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٥١"],[486,"الجزء: 15 - الصفحة: 456"],[487,"١٠٣٣ - الرواية عمن لحقه غفلة في وقت ما"],[488,"قال عبد اللَّه: قلت لأبي: إن بشر بن عمر زعم أنه سأل مالكًا عن صالح مولى التوأمة، فقال: ليس بثقة. قال أبي: مالك أدرك صالحًا وقد اختلط، وهو كبير، وما أعلم به بأسًا، من سمع منه قديمًا قد روى عنه أكابر أهل المدينة، نقلت ذلك من كتاب أبي بشر محمد بن أحمد الدولابي."],[489,"\"العدة\" ٣/ ٩٦٥ - ٩٦٦، \"المسودة\" ١/ ٥٣٠."],[490,"١٠٣٤ - من روى حديثا لا أصل له، وقال: سهوت فيه أو أخطأت، هل يقبل خبره؟"],[491,"؟"],[492,"قال حرب: قال أحمد في الرجل إذا سها في الإسناد، فأخطأ فيه، ولا يتعمد ذلك: أرجو أن لا يكون به بأس."],[493,"\"مسائل حرب\" ص ٤٨٢."],[494,"١٠٣٥ - الرواية عن الحفاظ المتقنين الذين يقل خطؤهم"],[495,"روى الميموني عن أحمد قال: كان مالك من أثبت الناس، وقد كان يخطئ."],[496,"\"العلل\" رواية المروذي وغيره (٣٧١)"],[497,"وذكر الأثرم لأحمد أن ابن المديني كان يحمل على عمرو بن يحيى، وذكر له هذا الحديث: أن النبي -صلى الله عليه وآله وسلم- صلى على حمار، وقال: إنما هو على بعير، فقال أحمد: هذا سهل."],[498,"\"شرح علل الترمذي\" لابن رجب ١/ ١٦٠"],[499,"الجزء: 15 - الصفحة: 457"],[500,"١٠٣٦ - الرواية عمن يغلب عليهم الغلط في روايتهم"],[501,"قال الحسين بن منصور أبو علي السلمي النيسابوري: سئل أحمد عمن يكتبه حديثه؛ فقال: عن الناس كلهم إلَّا عن ثلاثة: صاحب هوى يدعو إليه، أو كذاب، أو رجل يغلط في الحديث فيرد عليه فلا يقبل."],[502,"\"شرح علل الترمذي\" لابن رجب ١/ ١١٠"],[503,"وقال أبو عثمان البرذعي: نا محمد بن يحيى النيسابوري قال: قلت لأحمد بن حنبل في علي بن عاصم، وذكرت له خطأه؛ فقال لي أحمد: كان حماد بن سلمة يخطئ -وأوما أحمد بيده- خطأً كثيرًا. ولم ير بالرواية عنه بأسًا."],[504,"\"شرح علل الترمذي\" لابن رجب ١/ ١١٣"],[505,"١٠٣٧ - حكم الرواية عن الضعفاء؟"],[506,"؟"],[507,"قال ابن هانئ: قيل له: فالضعفاء؟"],[508,"قال: قد يحتاج إليهم في وقتٍ."],[509,"كأنه لم ير بالكتاب عنهم بأسًا."],[510,"\"مسائل ابن هانئ\" (١٩٢٦)."],[511,"قال ابن هانئ: قيل له: يحدث الرجل عن الضعفاء مثل: عمرو بن مرزوق، وعمرو بن حكام، ومحمد بن معاوية، وعلي بن الجعد، وإسحاق بن أبي إسرائيل؟"],[512,"قال أبو عبد اللَّه: لا يعجبني أن يحدث عن بعضهم."],[513,"\"مسائل ابن هانئ\" (٢٣١٤)."],[514,"قال ابن هانئ: قيل له: فيحدث بالصحيح من حديثهم؟"],[515,"الجزء: 15 - الصفحة: 458"],[516,"قال: اعفني منه، قد رووا بمكة عن قوم ثقات، مثل أبي المليح وغيره أحاديث مناكير."],[517,"\"مسائل ابن هانئ\" (٢٣١٦)."],[518,"قال الأثرم: رأى أحمد بن حنبل يحيى بن معين بصنعاء يكتب صحيفة معمر عن أبان عن أنس، فإذا أطلع عليه إنسان كتمه، فقال له أحمد: تكتب صحيفة معمر عن أبان وتعلم أنها موضوعة؟ ! فلو قال لك قائل: أنت تتكلم في أبان ثم تكتب حديثه على الوجه؟ ! فقال: رحمك اللَّه يا أبا عبد اللَّه، أكتب هذِه الصحيفة عن عبد الرزاق عن معمر على الوجه فأحفظها كلها، وأعلم أنه موضوعة، حتى لا يجئ بعده إنسان فيجعل بدل أبان ثابتًا، ويرويها عن معمر عن ثابت عن أنس، فأقول له: كذبت! إنما هي عن معمر عن أبان لا عن ثابت."],[519,"\"شرح علل الترمذي\" لابن رجب ١/ ٨٩"],[520,"وقال في رواية ابن القاسم: ابن لهيعة ما كان حديثه بذاك، وما أكتب حديثه إلَّا للاعتبار والاستدلال، إنما قد أكتب حديث الرجل كأني استدل به مع حديث غيره يشده لا أنه حجة إذا انفرد."],[521,"وقال في رواية المروذي: كنت لا أكتب حديث جابر الجعفي ثم كتبته أعتبر به."],[522,"وقال في رواية مهنا -وسأله لمَ تكتب حديث أبي بكر بن أبي كريم وهو ضعيف- قال: أعرفه."],[523,"وقال محمد بن رافع النيسابوري: رأيت أحمد بين يدي يزيد بن هارون وفي يده كتاب لزهير عن جابر الجعفي وهو يكتبه، قلت: يا أبا عبد اللَّه: تنهونا عن جابر وتكتبوه؟ !"],[524,"الجزء: 15 - الصفحة: 459"],[525,"قال: نعرفه."],[526,"وكذا قال أحمد في حديث عبيد اللَّه الوصافي: إنما أكتبه للمعرفة."],[527,"\"شرح علل الترمذي\" لابن رجب ١/ ٩١ - ٩٢"],[528,"١٠٣٨ - إذا كان في الحديث رجلان: قوي وضعيف، هل يجوز أن يحدث القوى فقط؟"],[529,"؟"],[530,"نقل عنه حرب: إذا كان في الحديث رجلان: قوي وضعيف، لم يجز أن يحدَّث عن القوي فقط."],[531,"\"المسودة\" ١/ ٥٢٩"],[532,"١٠٣٩ - هل يمنع التدليس من قبول الخبر؟"],[533,"؟"],[534,"قال أبو داود: سمعتُ أحمد يقول في الشيء من الحديث خفي عليه عن المحدث فيقول -يعني: عن فلان، وقال: لم أفهم جيدًا."],[535,"\"مسائل أبي داود\" (١٨١٥)"],[536,"قال أبو داود: سمعتُ أحمد سئل عن المحدث يذكرُ الحديث فيقال: من دون فلان فيقول: فلان، هو جائز؟ قال: نعم."],[537,"قلت: يؤلفه؛ أعني: الذي يسمعه هكذا؟ قال: يؤلفه وهل كان شريك يحدث إلَّا هكذا؛ كان يذكرُ الحديث فيقال: من ذكره؟ فيقول: فلان، فيقال: عمن؟ فيقول: فلان."],[538,"\"مسائل أبي داود\" (١٨١٦)"],[539,"نقل مهنا عنه، وقد قيل له: كان شعبة يقول: التدليس كذب، فقال"],[540,"الجزء: 15 - الصفحة: 460"],[541,"أحمد: لا، قد دلَّس قوم نحن نروي عنهم."],[542,"\"العدة\" ٣/ ٩٥٧ - ٩٥٨، \"المسودة\" ١/ ٥٥٠."],[543,"وقال محمد بن مخلد: حدثنا حمدان بن علي الورَّاق قال: سمعت أحمد بن حنبل رحمه الله يقول: كان حجاج بن أرطاة يقول لهم: لا تقولوا من حدثك، ولا من أخبرك، قولوا: من ذكره يا أبا أرطاة."],[544,"قيل له: كان يدلس؟ قال: نعم."],[545,"\"العدة\" ٣/ ٩٥٩، \"بدائع الفوائد\" ٤/ ٥٣."],[546,"وقال مهنا: سألت أحمد عن هُشيم، فقال: ثقة، إذْ لم يُدلس."],[547,"فقلت له: والتدليس عيب هو؟ قال: نعم."],[548,"\"طبقات الحنابلة\" ٢/ ٤٣٦."],[549,"وقال أبو داود: سمعت أحمد سُئل عن رجل يعرف بالتدليس في الحديث يحتج به فيما لم يقل فيه: حدثني أو سمعت؟ قال: لا أدري."],[550,"\"المسودة\" ١/ ٥١٦، ٥٤٨."],[551,"الجزء: 15 - الصفحة: 461"],[552,"باب: التحمل والأداء"],[553,"١٠٤٠ - شرط التحمل: أن يكون ضابطا مميزا"],[554,"قال عبد اللَّه: سألت أبي: متى يجوز سماع الصبي في الحديث؟"],[555,"قال: إذا عقل وضبط."],[556,"قلت: فإنه بلغني عن رجل سميته له، أنه قال: لا يجوز سماعه حتى يكون له خمس عشرة سنة، لأن النبي -صلى الله عليه وآله وسلم- رد البراء، وابن عمر، استصغرهم يوم بدر (١)، فأنكر قوله هذا وقال: لا، بئس القول هذا، يجوز سماعه إذا عقل. وكيف يصنع بسفيان بن عيينة، ووكيع، وذكر أيضا قومًا."],[557,"\"مسائل عبد اللَّه\" (١٦٣٣)."],[558,"قال عبد اللَّه: قلت لأبي: ما تقول في سماع الضرير البصر؟"],[559,"قال: إذا كان يحفظ من المحدث فلا بأس، وإن لم يكن يحفظ فلا."],[560,"قلت لأبي: فالأمي؟ قال: هو كذلك بهذِه المنزلة، إلَّا ما حفظ من المحدث."],[561,"\"مسائل عبد اللَّه\" (١٦٣٤)."],[562,"قال أحمد في رواية المروذي: لا ينبغي للرجل إذا لم يعرف الحديث أن يحدث به، ثم قد صار الحديث يحدث به من لم يعرفه."],[563,"وقال في الكبير لا يعرف الحديث ولا يعقل: إذا كتب، فلا بأس أن يرويه."],[564,"\"العدة\" ٣/ ٩٤٩."],[565,"قال أحمد في رواية أبي الحارث والمروذي وحنبل: يصح سماع الصغير إذا عقل وضبط."],[566,"\"المسودة\" ١/ ٥١٣"],[567,"(١) رواه الإمام أحمد ٤/ ٢٩٨، والبخاري (٣٩٥٥) من حديث البراء بن عازب."],[568,"الجزء: 15 - الصفحة: 462"],[569,"فصل: ما جاء في طرق تحمل الحديث"],[570,"قال أبو داود: سمعتُ أحمد يقولُ: أرجُو أن لا يكون العرض لا بأس به. يعني: قراءة الحديث على المحدث."],[571,"فقيل لأحمد: فكيف يعجبك أن يقول؟"],[572,"قال: يعجبني أن يقول كما يفعل، وإن قرأ قال: قرأتُ."],[573,"\"مسائل أبي داود\" (١٨١٧)"],[574,"قال ابن هانئ: سمعت أبا عبد اللَّه يقول: قيل لشعبة: ما ترى في القراءة؟"],[575,"قال: جيد بالغ."],[576,"\"مسائل ابن هانئ\" (٢٢٢٢)."],[577,"قال ابن هانئ: كنت أقرأ على أبي عبد اللَّه الحديث، وأنا انظر في كتابه وهو ينظر معي."],[578,"فقال لي: هذا أحب إليّ من أن أقرأ أنا عليك."],[579,"قلت لأبي عبد اللَّه: أقول حدثني أحمد؟"],[580,"قال: قل إن شئت، ولكن أحب إليّ أن تتبع الصدق، وما سمعت به قط."],[581,"\"مسائل ابن هانئ\" (٢٢٢٣)، (٢٢٢٤)."],[582,"قال حرب: سمعت إسحاق يقول: سمعت من ابن المبارك وأنا ابن خمس عشرة فكنت أعيا به إذ ذاك قال: فكنا إذا قمنا من المجلس عارضنا فتركت السماع لحال المعارضة."],[583,"\"مسائل حرب\" ص ٣٤٧"],[584,"الجزء: 15 - الصفحة: 463"],[585,"قال عبد اللَّه: حدثني أبي قال: حدثنا يحيى بن سعيد، عن شعبة قال: سألت منصورًا وأيوب عن القراءة فقالا جيد -يعني: العرض."],[586,"\"العلل\" رواية عبد اللَّه (٤٢٨٧)"],[587,"قال في رواية المروذي: إذا أعطيتك كتابي، وقلت لك: اروه عني، وهو من حديثي، فلا تبال سمعته أو لم تسمعْه."],[588,"وقال أبو بكر الخلال: أخبرني أبو المثنى العنبري أن أبا داود حدثهم أن أبا عبد اللَّه قال: لم أسمع من أبي توبة شيئًا، وإنما كتب إليّ بأحاديث."],[589,"قال أبو بكر الخلال: وكان محمد بن عوف الحمصي يحدثنا كثيرًا، فيكثر فيما نسمع منه من \"المسند\" خاصة، فيقول: أخبرني أبو ثور في كتابه إليَّ."],[590,"وقال عبد اللَّه: رأيت عبد الرحمن المتطبب جاء إلى أبي فقال: يا أبا عبد اللَّه، أخبرني هذين الكتابين، فقال له: ضعهما، فأخذهما أبي، فعارض بهما حرفًا حرفًا، فلما جاء دفعهما إليه، وقال: قد أجزت لك هذِه بهذا."],[591,"\"العدة\" ٣/ ٩٨٢ - ٩٨٣، \"المسودة\" ١/ ٥٦٥."],[592,"قال ابن زنجويه: لَمَّا رجعنا من مصر دخلنا على أحمد بن حنبل فقال: مَرَرْتُم بأبي حفص عمرو بن أبي سلمة؟ قال: فقلنا له: وما كان عند أبي حفص؟ إنما كان عنده خمسون حديثًا للأوزاعي، والباقي مناولة."],[593,"فقال: والمناولة كنتم تأخذون منها وتنظرون فيها؟ !"],[594,"\"طبقات الحنابلة\" ١/ ٤٠١ - ٤٠٢."],[595,"قال حنبل: قال أحمد: لا بأس بالقراءة إذا كان رجل يعرف ويفهم ويبين ذلك."],[596,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٤٦"],[597,"الجزء: 15 - الصفحة: 464"],[598,"وقال حنبل: قال أبو عبد اللَّه: المناولة لا أدري ما هي حتى يعرف المحدث حديثه، وما يدريه ما في الكتاب؟ !"],[599,"قال: وأهل مصر يذهبون إلى هذا وأنا لا يعجبني."],[600,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٦٢"],[601,"قال في رواية الأثرم: كان شعيب بن أبي حمزة عسرًا في الحديث، فسألوه أن يأذن لهم أن يرووا عنه، فقال: لا ترووا هذِه الأحاديث عني. ثم كلموه وحضر ذلك أبو اليمان، فقال لهم: أرووا تلك الأحاديث عني."],[602,"قيل لأبي عبد اللَّه: مناولة؟"],[603,"قال: لو كان مناولة كان لم يعطهم كتبًا ولا شيئًا، إنما سمع هذا فقط."],[604,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٦٤"],[605,"الجزء: 15 - الصفحة: 465"],[606,"فصل: ما جاء في صيغ الأداء"],[607,"قال أبو داود: قيل لأحمد: كأن أخبرنا أسهل من حدثنا؟"],[608,"قال: نعم هو أسهلُ، حدثنا شديد."],[609,"\"مسائل أبي داود\" (١٨٢٠)"],[610,"قال أبو داود: قلتُ لأحمد: إذا سمع الرجل وحده يقول: حدثنا؟"],[611,"قال: لا بأس."],[612,"\"مسائل أبي داود\" (١٨٢٢)."],[613,"قال حرب: حدثنا عبد اللَّه بن أحمد بن معدان قال: حدثنا أحمد بن حنبل، حدثنا عبد الرزاق قال: حدثنا معمر، فقيل له: يا أبا عبد اللَّه، إن عبد الرزاق كان لا يقول: حدثنا، فقال أحمد: حدثنا وأخبرنا عندنا واحد، إن كان سماعًا من الشيخ."],[614,"وقال في رواية حنبل: وقيل له: سأل عوف الحسن فقال له: أقرأ عليك فأقول: حدثنا الحسن؟ قال: نعم."],[615,"قال حنبل: سألت أحمد عن ذلك؛ فقال: لا، ولكن يقول: قرأتُ."],[616,"\"العدة\" ٣/ ٩٧٧، \"المسودة\" ١/ ٥٦٢، ٥٦٤."],[617,"قال القاضي أبو يعلى: ذكر أبو إسحاق إبراهيم بن أحمد بن عمر بن شاقلا في تعاليقه في كتاب \"العلل\": سمعت أبا محمد عبد الخالق بن الحسن بن محمد بن نصر السقطي يقول: سألت ابن منيع فيما يقرؤه على الناس ويُقرأ عليه؟ فقال لي: سألت أحمد بن حنبل عما سألتني عنه فقال لي: إذا قرأ عليك فقل: حدثنا وإذا قُرئ عليه فقل: حدثنا فلان قراءة عليه."],[618,"\"العدة\" ٣/ ٩٧٨"],[619,"قال أحمد في رواية حنبل: إذا قال الشيخ: حدثنا، قلت: حدثنا، تتبع"],[620,"الجزء: 15 - الصفحة: 466"],[621,"لفظ الشيخ إنما هو دين، ولا يقول لـ (أخبرنا): حدثنا، ولا لـ (حدثنا): أخبرنا على لفظ الشيخ."],[622,"وقال أبو محمد الحسن بن محمد: سمعت جعفر بن هارون النحوي يقول: سمعت عبد اللَّه بن أحمد الكسائي قال: سمعت أحمد بن عبد الجبار يقول: سمعت أحمد بن حنبل يقول: حدثنا وأخبرنا واحد."],[623,"\"العدة\" ٣/ ٩٨١، \"الروايتين والوجهين/ المسائل الأصولية\" ص ٤٦، \"المسودة\" ١/ ٥٦٥"],[624,"نقل حنبل عنه: إذا قرأ والشيخ ساكت يسمع ولم يقل له هو كما قرأت عليه، فيقول: نعم، أو يقول له ابتداء: أقرأ عليك، فيقول: اقرأ، فإذا لم يفعل شيئًا من هذا فهل يجوز أن يقول: حدثني أو أخبرني: يسوغ له إذا كان ثقة ويقول قرأت على فلان فلم ينكره."],[625,"\"الروايتين والوجهين/ المسائل الأصولية\" ص ٦٣"],[626,"قال عبد اللَّه: سُئل أبي عن الرجل يسمع الحديث بلفظ الشيخ وتارة يسمعه بقراءته وهو يسمع، كيف يقول إذا حدث؟ قال: يقول كما قال."],[627,"قال عبد اللَّه: سمعت أبي يقول: إذا سمعت من المحدث فقل حدثنا، وإذا قرأت عليه فقل قرأت وإذا قرئ عليه فقل قرئ عليه."],[628,"\"الروايتين والوجهين/ المسائل الأصولية\" ص ٦٤"],[629,"قال أبو اليمان الحكم بن نافع: قال لي أحمد بن حنبل: كيف سمعت الكتب من شُعيب بن أبي حمزة؟"],[630,"قلت: قرأت عليه بعضه، وبعضه قرأهُ عليَّ، وبعضه إجَازَة، وبعضه مُناولة، فقال: قُل في كلَّه: أخبرنا شعيب."],[631,"\"طبقات الحنابلة\" ١/ ٣٩٩، \"المسودة\" ١/ ٥٦٩، \"شرح علل الترمذي\" لابن رجب ١/ ٢٦٥ - ٢٦٦"],[632,"الجزء: 15 - الصفحة: 467"],[633,"وقال سلمة بن شبيب: سمعت أحمد غير مرة يقول: حدثنا وأخبرنا واحد."],[634,"\"المسودة\" ١/ ٥٦٢"],[635,"قال عبد اللَّه: قال أبي: قد كان أبو معاوية الضرير إذا حدثنا بالشيء الذي يرى أنه لم يحفظه يقول: في كتابنا، أو في كتابي، عن أبي إسحاق الشيباني، ولا يقول: حدثنا ولا سمعت."],[636,"\"المسودة\" ١/ ٥٧٣."],[637,"قال إبراهيم بن ديزيل: سمعت أبا اليمان يقول: قال لي أحمد بن حنبل: كيف سمعت الكتب من شعيب؟"],[638,"قلت: قرأت عليه بعضه، وبعضه قرأه عليّ، وبعضه أجاز لي، وبعضه مناولة، قال: فقل في كله: أخبرنا شعيب."],[639,"\"سير أعلام النبلاء\" ١٠/ ٣٢١."],[640,"وروى حنبل بن إسحاق والأثرم قالا: نا أبو عبد اللَّه، نا محمد ابن الحسن الواسطي، ثنا عوف، أن رجلًا قال للحسن: معي أحاديث فإن لم تكن ترى بالقراءة بأسًا قرأت عليك؟"],[641,"قال: ما أبالي قرأت عليك، أو قرأت عليّ وأخبرتك أنه حديثي، أو حدثتك به."],[642,"قال: يا أبا سعيد، فأقول: حدثني الحسن؟ قال: نعم."],[643,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٤٠"],[644,"وذكر الخلال عن علي بن عبد الصمد المكي قال: قلت لأحمد بن حنبل -ونحن في مجلس نسمع فيه الحديث وأنا لا انظر في النسخة: يا أبا عبد اللَّه، يجزيني أن لا انظر في النسخة فأقول: حدثنا، مثل الصك، إذا لم ينظر فيه ويشهد؟"],[645,"الجزء: 15 - الصفحة: 468"],[646,"قال لي: لو نظرت في الكتاب كان أطيب لنفسك."],[647,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٥٢"],[648,"وقال أبو القاسم البغوي: كان أحمد لا يرى في العرض والإجازة (أنا) ولا (ثنا)، إنما رأيه أن يبين الراوي كما كان."],[649,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٥٦"],[650,"وقال الأثرم: قلت لأبي عبد اللَّه: أليس هذا جائزًا أن يقول: حدثني، وهو ينوي أنه قد حدثه فيمن حدث، ويقول: أشهدني، وقد أشهد جماعة؟"],[651,"قال: فظننت أنه سهل في ذلك."],[652,"\"شرح علل الترمذي\" لابن رجب ١/ ٢٦٠"],[653,"١٠٤١ - إن كان في سماعه عن فلان فهل يجوز أن يقول قال فلان أم لا؟"],[654,"؟"],[655,"نقل الحسن بن محمد بن الحارث السجستاني عن أحمد: إذا كان عن فلان في كتاب قال فلا يغيره."],[656,"قال أبو بكر الخلال: هذا وهم من الحسن بن محمد؛ لأن هذا عند أحمد تشديد."],[657,"\"الروايتين والوجهين/ المسائل الأصولية\" ص ٦٤"],[658,"الجزء: 15 - الصفحة: 469"],[659,"فصل: كيفية الأداء"],[660,"١٠٤٢ - جمع الحديث عن اثنين أو أكثر إذا اتفق في المعنى"],[661,"قال حرب: قيل فإذا كان الحديث عن ثابت وأبان، عن أنس، يجوز أن أسمي ثابتًا وأترك أبان؟"],[662,"قال: لا تقل، في حديث أبان شيء ليس في حديث ثابت، وقال: إذا كان هكذا فأحب إليَّ أن تسميهما."],[663,"\"مسائل حرب\" ص ٤٦٩."],[664,"١٠٤٣ - ما جاء في تقطيع الحديث"],[665,"قال ابن هانئ: سألت أبا عبد اللَّه عن الرجل يسمع الحديث، وهو إسناد واحد، فيقطعه ثلاثة أحاديث؟"],[666,"قال: لا يلزمه كذب، وينبغي له أن يحدث بالحديث كما سمع، ولا يغيره."],[667,"\"مسائل ابن هانئ\" (١٩١٨)"],[668,"قال أبو الحارث: كتبت إلى أبي عبد اللَّه أسأله عن تقطيع الأحاديث إذا أراد الرجل منه كلمة، والحديث طويل، فقال: إذا كان يحتاج من الحديث إلى حرف يريد أن يقتصر لطوله، فأرجو ألَّا يكون عليه شيء."],[669,"قال: ورأيت أبا عبد اللَّه قد أخرج أحاديث، أخرج حاجته من الحديث وترك الباقي، يخرج من أول الحديث شيئًا ومن آخره شيئًا ويدع الباقي."],[670,"الجزء: 15 - الصفحة: 470"],[671,"وذكر الأثرم في كتاب \"العلل\" قال: ذكر أبو عبد اللَّه حديث طلق بن علي في المسكر الذي ذكر فيه: لا يشربه رجل ابتغاء لذة سكر (١)، ربما يذكر: تركت هذِه الكلمة: ابتغاء لذة سكر، مخافة أن يتأولوها على غير تأويلها، ونقل هذا."],[672,"قال أبو بكر الخلال: قد حكى اختصار الحديث عن أبي عبد اللَّه جماعة، وبين عنه أبو الحارث، وذكر عنه الفضل بن زياد وأبو أمية الطرسوسي اختصارًا لا يكون شيء أبين ولا أحسن اختصارًا من حديث الإسراء وحديث النعمان بن بزرج، وهذان الحديثان كل واحد منهما في أوراق."],[673,"وذكر أبو بكر الخلال في باب غسل الحائض من كتاب \"العلل\" عن المروذي، وذكر لأحمد حديث ابن أبي شيبة عن وكيع، كأنه اختصره، فقال: ويحك يحل له أن يختصر."],[674,"قال أبو بكر الخلال: أبو عبد اللَّه لا يرى بأسًا باختصار الحديث، وابن أبي شيبة اختصر في غير موضع الاختصار."],[675,"\"العدة\" ٣/ ١٠١٥ - ١٠١٨."],[676,"(١) رواه ابن سعد في \"الطبقات\" ٥/ ٥٦٢، وابن أبي شيبة ٥/ ٦٥ (٢٣٧٣٣)، والبخاري في \"التاريخ الكبير\" ٤/ ٢٠٥ من طريق سراح بن عقبة، عن عمته خالدة، عن أبيها طلق. . الحديث."],[677,"الجزء: 15 - الصفحة: 471"],[678,"١٠٤٤ - رواية الحديث بالمعنى"],[679,"قال صالح: قلت لأبي: يكون في الحديث: قال رسول اللَّه -صلى الله عليه وآله وسلم-، فيجعله الإنسان: قال النبي -صلى الله عليه وآله وسلم-، فقال: أرجو أن لا يكون به بأس."],[680,"وقال صالح: قلت: الشيخ يدغم الحرف يعرف أنه كذا وكذا ولا يفهم عنه، ترى أن يروى ذلك عنه؟"],[681,"قال: أرجو ألا يضيق عليه هذا."],[682,"\"سيرة الإمام أحمد\" رواية صالح (٢٣)"],[683,"قال عبد اللَّه: حدثني أبي قال: حدثنا جابر بن سُليم الأنصاري قال: سمعت جَرُم بن أبي راشد، عن ابن أبي عتيق، عن عبد اللَّه بن عمرو قال: إذا حدثك الرجل حديثًا، فقدم وأخر، فقد أدى ما عليه."],[684,"\"العلل\" رواية عبد اللَّه (٤٥٠)"],[685,"قال مهنا: قلت لأحمد: سمعت عبد الرزاق يقول: قال بعض أصحابنا لسفيان الثوري: يا أبا عبد اللَّه حدثنا كما سمعت، فقال: واللَّه ما إليه سبيل، وما هو إلَّا المعاني."],[686,"فقال أحمد: هو كذلك."],[687,"\"المسائل التي حلف عليها الإمام أحمد\" ص ١٠٠، \"طبقات الحنابلة\" ٢/ ٤٣٦."],[688,"قال أحمد في رواية حرب والميموني والفضل بن زياد وأبي الحارث: تجوز الرواية على المعنى."],[689,"وقال: ما زال الحفاظ يحدثون بالمعنى."],[690,"\"العدة\" ٣/ ٩٦٩."],[691,"قال عمر المغازلي: قال أحمد بن حنبل: قال رسول اللَّه -صلى الله عليه وآله وسلم-، وقال النبي -صلى الله عليه وآله وسلم-، واحد، فألزمه بعض أصحابنا حديث البراء بن عازب:"],[692,"الجزء: 15 - الصفحة: 472"],[693,"رسولك الذي أرسلت، قال: لا، \"ونبيك الذي أرسلت\" (١). قال: هذا لا يلزم؛ لأنه كان نبيًّا ثم أرسل، فقال: ونبيك الذي أرسلت، ولم يقل: ورسولك الذي أرسلت؛ لأنه لا تكون رسالة بعد رسالة، وإنما أراد رسالة بعد نبوة."],[694,"\"العدة\" ٣/ ٩٧٣."],[695,"١٠٤٥ - الحديث يجيء فيه اللحن والشيء الفاحش هل يغيره؟"],[696,"؟"],[697,"قال أبو داود: قلتُ لأحمد: وجدتُ في كتابي: حجاج عن جرير، عن أبي الزبير، عن جابر، يجوز أن أصلحه ابن جريج، قال: أرجو أن يكون هذا لا بأس به."],[698,"\"مسائل أبي داود\" (١٨٢٣)."],[699,"قال ابن هانئ: سمعت ابن زنجويه يسأل أبا عبد اللَّه: يجيء الحديث اللحن، وشيء فاحش. فترى أن يغير أو أن يحدث به كما سمع."],[700,"قال: يغيره شديدًا، إن النبي -صلى الله عليه وآله وسلم- وأصحابه لم يكونوا يلحنون إنما يجيء اللحن ممن هو دونهم يغير شديدًا."],[701,"\"مسائل ابن هانئ\" (٢٢٩٤)، (٢٢٩٤)"],[702,"قال الخلال: أخبرني يوسف بن موسى، أن أبا عبد اللَّه قيل له: الرجل يكتب الحديث؛ فيجيء الحديث: على وعثمان، أيكتب هو: عثمان وعلي؟"],[703,"قال: لا بأس."],[704,"\"السنة\" للخلال ١/ ٢٩٧ (٥٣٦)"],[705,"(١) رواه الإمام أحمد ٤/ ٢٩٣، والبخاري (٢٤٧)، ومسلم (٢٧١٠)."],[706,"الجزء: 15 - الصفحة: 473"],[707,"وقال عبد اللَّه بن أحمد: كان أبي إذا قرأ الحديث، وكان بجانبه من يبصر النحو يقول له: كذا فيصلحه، أو نحو هذا من الكلام."],[708,"\"المسودة\" ١/ ٥٧١ - ٥٧٢."],[709,"١٠٤٦ - إذا وجد الرجل في كتاب غيره من لا يحدث عنهم هل يضرب عليهم؟"],[710,"؟"],[711,"قال صالح: سألت أبي عن رجل أوصى رجلًا، وله في يده كتاب وفيه قوم لا يستأهلون أن يحدث عنهم، فقالوا: اضرب عليهم فلم يفعل حتى مات، فترى أن يضرب على هؤلاء أو يستأمر ورثته."],[712,"قال: يضرب عليهم."],[713,"\"مسائل صالح\" (٥١٨)"],[714,"الجزء: 15 - الصفحة: 474"],[715,"باب: كتابة الحديث وتدوينه"],[716,"١٠٤٧ - تدوين الحديث، وذكر من كره ذلك"],[717,"قال إسحاق: قلت لأحمد: من كره كتابة العلم؟"],[718,"قال: كرهه قومٌ كثير، ورخَّص فيه قومٌ."],[719,"قلت: فلو لم يكتب لذهب العلمُ؟"],[720,"قال: ولولا كتابته أي شيء كنا نحن."],[721,"قال إسحاق: كما قال."],[722,"\"مسائل الكوسج\" (٣٢٧٣)"],[723,"قال صالح: حدثني أبي قال: حدثنا هشيم قال: أخبرنا ابن عون قال: دخلنا على الحسن، فأخرج لنا كتابًا من سمرة، فإِذا فيه: إِنه يجزئ من الاضطرار صبوح أو غبوق، قال: نبئت أنها كتب."],[724,"\"مسائل صالح\" (٦٣٧)"],[725,"قال صالح: قال أبي: ورآني يومًا وأنا أكتب في الألواح، فقال لي: أتكتب؟ !"],[726,"\"مسائل صالح\" (٧٠٢)"],[727,"قال صالح: قال أبي: كنا عند إسماعيل بن إبراهيم، فجاء إنسان فذكر حديث محمد بن إسحاق، عن عمرو بن شعيب، عن أبيه، عن جده قال: قلت: يا رسول اللَّه! أكتب عنك ما أسمع منك؟"],[728,"قال: \"نعم\"."],[729,"قلت: يا رسول اللَّه، في الرضا والغضب؟"],[730,"الجزء: 15 - الصفحة: 475"],[731,"قال: \"نعم، فإنه لا ينبغي لي أن أقول في ذلك إلَّا حقًّا\" (١)."],[732,"قال: فقال إسماعيل: أعوذ باللَّه من الكذب وأهله، وأعوذ باللَّه من الكذب وأهله."],[733,"قال: كان ابن عون وابن سيرين لا يَكْتبون ولا يُكَتبون."],[734,"قال أبي: قال إسماعيل: قال ابن عون: أرى هذِه الكتب سيكون لها غب سوءٍ."],[735,"قال صالح: حدثني أبي قال: حدثنا إسماعيل قال: حدثنا همام، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"لا تكتبوا عني شيئًا\" (٢)."],[736,"قال أبي: إنما أنكر إسماعيل قصة عمرو بن شعيب من أجل حديث همام."],[737,"\"مسائل صالح\" (٨٠٩)"],[738,"(١) رواه الإمام أحمد ٢/ ٢١٥، والبزار في \"البحر الزخار\" ٦/ ٤٣٧ (٢٤٧٠) عن طريق محمد بن إسحاق به. قال الشيخ أحمد شاكر في تعليقه على \"المسند\" (٧٠٢٠): إسناده صحيح، ورواه الإمام أحمد أيضًا ٢/ ١٦٢، ١٩٢، وأبو داود (٣٦٤٦)، والدارمي ١/ ٤٢٩ (٥٠١)، والحاكم ١/ ١٠٥ - ١٥٦ من طريق عبيد اللَّه بن الأخنس، عن الوليد بن عبد اللَّه، عن يوسف بن مالك من عبد اللَّه بن عمرو به. قال الحاكم: رواة هذا الحديث قد احتجا بهم عن آخرهم غير الوليد هذا، وأظنه الوليد بن أبي الوليد الشامي. وقال الشيخ أحمد شاكر في تعليقه على \"المسند\" (٦٥١٠، ٦٨٠٢): إسناده صحيح. (٢) رواه الإمام أحمد ٣/ ١٢، ومسلم (٣٠٠٤)."],[739,"الجزء: 15 - الصفحة: 476"],[740,"قال صالح: حدثني أبي قال: حدثنا وكيع، عن مسكين -قال وكيع: أبو هريرة التيمي وكان ثبتًا- قال: كنا جلوسًا عند عطاء ونحن نسائله إذ جاء رجل بصحيفة، فقال: يا أبا محمد، إني من أرض شاسعة قليل علماؤها، فأنا أحب أن تكتب لي ما سمعت من أصحاب النبي -صلى الله عليه وآله وسلم- الذي حدثهم به مما أمرهم به ونهاهم ليس في القرآن."],[741,"قال: فقال له عطاء: وترضى بما قال أصحاب رسول اللَّه -صلى الله عليه وآله وسلم-؟"],[742,"قال: وما لي لا أرضى؟"],[743,"قال: فإن رسول اللَّه -صلى الله عليه وآله وسلم- لما مضى، اجتمع أصحابه فقالوا: نكتب ما أمرنا به ونهينا عنه مما ليس في القرآن."],[744,"قال: ثم أجمع رأيهم على أن بني إسرائيل إنما تفرقت في الكتب. فلست بكاتب لك شيئًا."],[745,"\"مسائل صالح\" (١٤٠١)"],[746,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا أبي عن عبد اللَّه بن حنش قال: رأيتهم يكتبون على أكفهم بالقصب عند البراء."],[747,"\"العلل\" رواية عبد اللَّه (٢٣١)"],[748,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع، عن عكرمة بن عمار، عن يحيى، عن ابن عباس: قيدوا العلم بالكتاب، من يشتري مني علمًا بدرهم."],[749,"\"العلل\" رواية عبد اللَّه (٢٣٢)"],[750,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع، عن ابن عون، عن محمد قلت لعبيدة: أكتب؟ قال: لا، قال: وجدت كتابًا أقرأه؟ قال: لا."],[751,"\"العلل\" رواية عبد اللَّه (٢٣٣)"],[752,"الجزء: 15 - الصفحة: 477"],[753,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثني المنذر بن ثعلبة، عن علباء بن أحمر اليشكري قال: قال علي: من يشتري مني علمًا بدرهم؟"],[754,"\"العلل\" رواية عبد اللَّه (٢٣٤)"],[755,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع، عن الحكم بن عطية، عن محمد: كانوا يرون أن إسرائيل إنما ضلوا من كتب وجدوها عن آبائهم."],[756,"\"العلل\" رواية عبد اللَّه (٢٣٥)"],[757,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثني طلحة بن يحيى، عن أبي بردة قال: كنت كتبتُ عن أبي كتابًا فدعا بمِركَن ماء فغسله فيه."],[758,"\"العلل\" رواية عبد اللَّه (٢٣٦)"],[759,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع عن شريك، عن مغيرة، عن إبراهيم قال: كنت أكتب عند عبيدة فقال: لا تخلدن عني كتابًا."],[760,"\"العلل\" رواية عبد اللَّه (٢٣٧)"],[761,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا عمران -يعني: ابن حُدير- عن لاحق، عن بشير بن نهيك قال: كنت كتبت عن أبي هريرة كتابًا، فلما أردت أن أفارقه قلت: يا أبا هريرة، إني كتبت عنك كتابًا، فأرويه عنك؟ قال: نعم."],[762,"\"العلل\" رواية عبد اللَّه (٢٣٨)"],[763,"قال عبد اللَّه: حدثني أبي قال: حدثنا إسحاق بن سليمان الرازي قال: سمعت أبا جعفر عن الربيع بن أنس قال: مكتوب في الكتاب الأول: ابن آدم علم مجانًا كما علمت مجانًا."],[764,"\"العلل\" رواية عبد اللَّه (٢٣٩)"],[765,"الجزء: 15 - الصفحة: 478"],[766,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا سفيان عن النعمان بن قيس: أن عبيدة أوصى أن تحرق كتبه أو تمحى."],[767,"\"العلل\" رواية عبد اللَّه (٢٤٠)"],[768,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا شريك قال: سمعت شيخًا في المسجد فوصفته فقال: ذاك أبو صخرة جامع بن شداد قال: رأيت حمادًا يكتب عند إبراهيم وعليه أنبجاني وهو يقول: واللَّه ما أريد به الدنيا."],[769,"\"العلل\" رواية عبد اللَّه (٢٤١)"],[770,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا الأعمش، عن إبراهيم قال: قال مسروق لعلقمة: اكتب لي النظائر، قال: أما علمت أن الكتاب يكره، قال: إنما أتعلمه، ثم أمحاه، قال: لا بأس."],[771,"\"العلل\" رواية عبد اللَّه (٢٤٢)"],[772,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثني الحسن بن عقبة -يعني: أبا كيران- قال: سمعت الشعبي يقول: إذا سمعت شيئًا فاكتبه ولو في الحائط."],[773,"\"العلل\" رواية عبد اللَّه (٢٤٣)"],[774,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا سفيان عن محمد بن الزبير قال: رأيت عمر بن عبد العزيز، رأى ابنا له كتب في الحائط ذكر اللَّه، فضربه."],[775,"\"العلل\" رواية عبد اللَّه (٢٤٤)"],[776,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثني حسين بن عقيل قال: أملى عليّ الضحاك مناسك الحج."],[777,"\"العلل\" رواية عبد اللَّه (٢٤٥)"],[778,"الجزء: 15 - الصفحة: 479"],[779,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا الوليد بن ثعلبة عن عبد اللَّه مؤذن الضحاك، عن الضحاك قال: لا تتخذوا للحديث كراريس ككراريس المصاحف."],[780,"\"العلل\" رواية عبد اللَّه (٢٤٦)"],[781,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: حدثنا حسن عن ليث، عن مجاهد أنه كره الكراريس."],[782,"\"العلل\" رواية عبد اللَّه (٢٤٧)"],[783,"قال عبد اللَّه: حدثني أبي قال: حدثنا وكيع قال: وجدناه عند أبي عوانة عن سليمان بن أبي عتيك، عن أبي معشر، عن إبراهيم أنه كره الكراريس."],[784,"\"العلل\" رواية عبد اللَّه (٢٤٨)"],[785,"قال عبد اللَّه: حدثني أبي قال: حدثنا حجاج قال: حدثني مندل عن جعفر بن أبي المغيرة، عن سعيد بن جبير قال: كنت أكتب عند ابن عباس في ألواحي حتى أملاها، ثم أكتب في نعلي."],[786,"\"العلل\" رواية عبد اللَّه (٢٨٩)"],[787,"قال عبد اللَّه: حدثني أبي قال: حدثنا إسماعيل بن إبراهيم، عن ابن عون، عن محمد: كان يكره الكتاب."],[788,"قال عبد اللَّه: حدثني أبي قال: حدثنا إسماعيل قال: حدثني همام، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري، عن النبي -صلى الله عليه وآله وسلم-: \"لا تكتبوا عني شيئًا\"، هذا معناه."],[789,"\"العلل\" رواية عبد اللَّه (٣٢٤ - ٣٢٥)"],[790,"قال عبد اللَّه: سمعت أبي يقول: سمعت أن قَلَّ رجل يأخذ كتابًا ينظر فيه إلَّا استفاد منه شيئًا."],[791,"\"العلل\" رواية عبد اللَّه (٢٣٩٣)"],[792,"الجزء: 15 - الصفحة: 480"],[793,"قال رجاء بن أبي رجاء المروذي: قلت لأحمد بن حنبل: أريد أن أعرف الحديث. قال: إن أردت أن تعرف الحديث فأكثر من الكتاب."],[794,"\"طبقات الحنابلة\" ١/ ٤١٧"],[795,"قال حرمي بن يونس: أتيتُ أبا عبد اللَّه، فسألتُهُ عن حديث، فقال: نعم، حق أخرجه لك، قال: فلما كان في نصف النهار إذا رجل يدق على الباب."],[796,"قال: فخرجت، فإذا أبو عبد اللَّه، فقلت: حاجة؟"],[797,"قال: نعم."],[798,"قلت: تدخل؟"],[799,"قال: نعم، فدخل، فأخرج إليَّ رقعة فيها أحاديث، فقرأها عليَّ ثم أبرد عندي ومضى."],[800,"\"طبقات الحنابلة\" ١/ ٤٠٣ - ٤٠٤"],[801,"قال أبو شعيب الحراني: سمعت علي بن المديني يقول: قال لي سيدي أحمد بن حنبل: لا تحدث إلَّا من كتاب."],[802,"\"المناقب\" لابن الجوزي ص ١٢٠"],[803,"وقال الخلال: أخبرني الميموني أنه قال لأبي عبد اللَّه: قد كره قوم كتاب الحديث بالتأويل؟"],[804,"قال: إذا يخطئون إذا تركوا كتاب الحديث."],[805,"وقال: حدثونا قوم من حفظهم وقوم من كتبهم، فكان الذي حدثونا من كتبهم أتقن."],[806,"\"شرح علل الترمذي\" لابن رجب ١/ ٤٢"],[807,"الجزء: 15 - الصفحة: 481"],[808,"١٠٤٨ - حكم كتابة الحديث بالأجرة"],[809,"قال ابن جامع الأنباري: وسألته عن كتابة الحديث بالأجرة فلم ير به بأسًا، وكتابة القرآن أيضًا."],[810,"\"بدائع الفوائد\" ٤/ ٤٥"],[811,"١٠٤٩ - كراهة كتابة ما دون الحديث"],[812,"قال ابن هانئ: سمعت أبا عبد اللَّه يقول: لا يعجبني شيء من وضع الكتب، ومن وضع شيئًا من الكتب، فهو مبتدع."],[813,"\"مسائل ابن هانئ\" (١٩٠٨)"],[814,"قال ابن هانئ: سألت أبا عبد اللَّه عن كتاب مالك، والشافعي أحب إليك، أو كتب أبي حنيفة، وأبي يوسف؟"],[815,"فقال: الشافعي أعجب إليّ، هذا وإن كان وضع كتابًا، فهؤلاء يفتون بالحديث، وهذا يفتي بالرأي، فكم بين هذين!؟"],[816,"\"مسائل ابن هانئ\" (١٩٠٩)"],[817,"قال ابن هانئ: وسمعت أبا عبد اللَّه وسأله رجل من أردييل عن رجل يقال له عبد الرحمن وضع كتبًا؟"],[818,"فقال أبو عبد اللَّه: قولوا له: أحد من أصحاب النبي -صلى الله عليه وآله وسلم- فعل هذا؟ أو أحد من التابعين؟ فاغتاظ وشدد في أمره، ونهى عنه."],[819,"وقال: انهوا الناس عنه وعليكم بالحديث."],[820,"\"مسائل ابن هانئ\" (١٩١٢)"],[821,"قال ابن هانئ: سألت أبا عبد اللَّه عن كتب أبي ثور؟"],[822,"فقال: كل كتاب ابتدع فهو بدعة."],[823,"\"مسائل ابن هانئ\" (١٩١٢)"],[824,"قال ابن هانئ: قيل له: فما كان من كلام إسحاق بن راهويه، وما كان من وضع في كتاب، وكلام أبي عبيد، ومالك، ترى النظر فيه؟"],[825,"الجزء: 15 - الصفحة: 482"],[826,"قال: كل كتاب ابتدع فهو بدعة، أو كل كتاب محدث فهو بدعة، وأما ما كان من مناظرة يخبر الرجل بما عنده، وما يسمع من الفتيا، فلا أرى به بأسًا."],[827,"\"مسائل ابن هانئ\" (١٩٢٣)"],[828,"قال ابن هانئ: قال أحمد: كل من وضع الكتب فلا يعجبني،، ويجرد الحديث."],[829,"\"مسائل ابن هانئ\" (٢٣٦٩)"],[830,"قال عبد اللَّه: سمعت أبي، وذكر وضع الكتب، فقال: أكرهها، هذا أبو حنيفة وضع كتابًا، فجاء أبو يوسف ووضع كتابًا، وجاء محمد بن الحسن فوضع كتابًا فهذا لا انقضاء له، كلما جاء رجل وضع كتابًا."],[831,"وهذا مالك وضع كتابًا، وجاء الشافعي أيضًا، وجاء هذا -يعني: أبا ثور- وهذِه الكتب وضعها بدعة، كلما جاء رجل وضع كتابًا، ويترك حديث رسول اللَّه -صلى الله عليه وآله وسلم-."],[832,"أو كما قال أبي هذا ونحوه."],[833,"وعاب وضع الكتب وكرهه كراهية شديدة."],[834,"وكان أبي يكره \"جامع سفيان\" وينكره، ويكرهه كراهية شديدة، وقال: من سمع هذا من سفيان؟"],[835,"ولم أره يصحح لأحد سمعه من سفيان، ولم يرض أبي أن يسمع من أحد حديثًا."],[836,"\"مسائل عبد اللَّه\" (١٥٨٢)"],[837,"قال عبد اللَّه: حدثني أبي قال: حدثنا إسماعيل بن علية، عن ابن عون: أحسب أو أرى يكون لهذِه الكتب غبٌّ غب سوء."],[838,"\"مسائل عبد اللَّه\" (٢٧٣٠)"],[839,"الجزء: 15 - الصفحة: 483"],[840,"١٠٥٠ - أول من صنف الكتب"],[841,"قال عبد اللَّه: قلت لأبي: أول من صنف الكتب؟"],[842,"قال: ابن جريج وابن أبي عروبة -يعني: ونحوها ولي- وقال ابن جريج: ما صنف أحد العلم تصنيفي."],[843,"\"العلل\" رواية عبد اللَّه (٢٣٨٣)"],[844,"١٠٥١ - ما جاء في الكتابة بخط دقيق"],[845,"قال ابن الجوزي: أخبرنا المبارك بن أحمد قال: أنا عبد اللَّه بن أحمد قال: أنا أحمد بن علي قال: أخبرني علي بن أحمد بن أبي حامد الأصبهاني في كتابه إليّ قال: ثنا محمد بن الحسين الآجري قال: ثنا محمد بن مخلد قال: سمعت حنبل بن إسحاق يقول: رآني أحمد بن حنبل وأنا أكتب خطًّا دقيقًا فقال: لا تفعل، أحوج ما تكون إليه يخونك."],[846,"\"المناقب\" ص ٢٦٣ - ٢٦٤"],[847,"١٠٥٢ - ما جاء في ختم الكتاب"],[848,"سمعتُ أحمدَ يقولُ: ما لي خاتمٌ أكاد أختم كتابًا."],[849,"ورأيت أحمد يكتبُ مرارًا ولا يختمُ كتابهُ."],[850,"\"مسائل أبي داود\" (١٦٨٩)"],[851,"١٠٥٣ - ما جاء في دفن الكتب ومحو العلم"],[852,"قال المروذي: قلت لأبي عبد اللَّه: إن أبا هاشم زياد بن أيوب سألني أن أسألك: إن أبا حفص ابنه أوصى أن تدفن كتبه؟"],[853,"قال: ما يعجبني أن يدفن العلم."],[854,"\"الورع\" (٢٨٧)"],[855,"الجزء: 15 - الصفحة: 484"],[856,"قال المروذي: قلت لأبي عبد اللَّه: إن رجلًا سألني أن أسألك عن محمد بن الحسين، أوصى أن تدفن كتبه وله أولاد؟"],[857,"فقال: فيهم من أدرك؟"],[858,"قلت: نعم. قال: وعمّن كتب هذِه الكتب؟"],[859,"قلت: عن قومٍ صالحين -وقد كان أبو عبد اللَّه قد نظر في جزأين من كتبه، أريته أنا إياهما: \"كتاب الدفائن\" و\"كتاب المنتظم\". فقال لي: لا تشاغلن بهذا، عليك بالعلم عليك بالفقه."],[860,"ثم قال أبو عبد اللَّه: أكره أن أتكلم فيها، أحب العافية منها، ما أريد أن أتكلم فيها بشيء، واستعفى من أن يجيب في أن تترك أو تدفن."],[861,"\"الورع\" (٢٨٨)"],[862,"نقل بكر عن أبيه، عن أبي عبد اللَّه سمعه -وسئل عن رجلٍ أوصى إليه رجل أن يدفن كتبه- قال: ما أدري ما هذا؟"],[863,"وقال الأثرم: قلت لأبي عبد اللَّه: دفن دفاتر الحديث؟"],[864,"قال: أرجو أن لا يكون به بأس، سأله أبو طالب عن محو كتب الحديث، فقال: سبحان اللَّه تمحى السنة والعلم؟"],[865,"قلت: ما تقول؟ قال: لا."],[866,"وقال أبو طالب: سألت أبا عبد اللَّه، ما ترى في دفن العلم إذا كان الرجلُ يخاف أن ليس له خلف يقوم به ويخاف عليه الضيعة؟"],[867,"قال: لا يدفن، ولعل ولده ينتفع به، عبيدة أوصى أن تُدفن، والثوري لم يكن له ولدٌ ولعل غير ولده ينتفع به."],[868,"قلت: يباع؟ قال: لا يباعُ، ولكن يدعه لولده ينتفع به أو غير ولده ينتفع به."],[869,"\"الآداب الشرعية\" ٢/ ١١٤"],[870,"الجزء: 15 - الصفحة: 485"],[871,"باب: ما جاء في مصنفات الحديث"],[872,"فصل: ما جاء في \"مسند الإمام أحمد\""],[873,"\""],[874,"١٠٥٤ - سبب تأليف الإمام للمسند"],[875,"قال حنبل بن إسحاق: جمعنا عمي، لي ولصالح ولعبد اللَّه، وقرأ علينا المسند، وما سمعه منه -يعني: تامًّا- غيرنا، وقال لنا: إن هذا الكتاب قد جمعته وأتقنته من أكثر من سبعمائة وخمسين ألفًا، فما اختلف المسلمون فيه من حديث رسول اللَّه -صلى الله عليه وآله وسلم- فارجعوا إليه، فإن كان فيه وإلا فليس بحجة."],[876,"\"خصائص المسند\" لأبي موسى المديني ١/ ٢١، \"الفروسية\" ص ٢٠٨، \"المصعد الأحمد\" لابن الجزري ١/ ٣١"],[877,"قال عبد اللَّه: قلت لأبي رحمه اللَّه تعالى: لم كرهت وضع الكتب وقد عملت \"المسند\"؟ فقال: عملت هذا الكتاب إمامًا، إذا اختلف الناس في سنة رسول اللَّه -صلى الله عليه وآله وسلم- رُجع إليه."],[878,"\"خصائص المسند\" ١/ ٢٢"],[879,"١٠٥٥ - ما قصد الإمام جمعه من الحديث في \"المسند\""],[880,"\""],[881,"قال أبو موسى المديني: ذكر أبو العز بن كادش أن عبد اللَّه بن أحمد، قال لأبيه: ما تقول في حديث ربعي عن حذيفة؟ قال: الذي يرويه عبد العزيز بن أبي رواد؟"],[882,"الجزء: 15 - الصفحة: 486"],[883,"قلت: يصح؟ قال: لا، الأحاديث بخلافه، وقد رواه الخياط عن ربعي عن رجل لم يسموه."],[884,"قال: قلت له: فقد ذكرته في \"المسند\"، فقال: قصدت في \"المسند\" الحديث المشهور، وتركت الناس تحت ستر اللَّه تعالى، ولو أردت أن أقصد ما صح عندي، لم أرو من هذا \"المسند\" إلَّا الشيء بعد الشيء، ولكنك يا بني تعرف طريقتي في الحديث، لست أخالف ما ضعف إذا لم يكن في الباب ما يدفعه."],[885,"\"خصائص المسند\" ١/ ٢٧"],[886,"١٠٥٦ - وقت ابتداء الإمام في تصنيف \"المسند\"؟"],[887,"\"؟"],[888,"قال أبو موسى المديني: وجدت بخط أحمد بن محمد بن البرداني، عن أبي علي بن الصواف قال: سمعت عبد اللَّه بن أحمد يقول: صنف أبى \"المسند\" بعد ما جاء من عند عبد الرزاق."],[889,"\"خصائص المسند\" ١/ ٢٥"],[890,"١٠٥٧ - عدد أحاديث \"المسند\""],[891,"\""],[892,"قال أبو موسى المديني: وجدت بخط الشيخ حامد بن أبي الفتح، ذكره أبو عبد اللَّه الحسين بن أحمد الأسدي في كتابه المسمى \"مناقب أحمد بن حنبل\" أنه سمع أبا بكر بن مالك، يذكر أن جملة ما وعاه المسند أربعون ألف حديث غير ثلاثين أو أربعين، قال: وسمعته."],[893,"\"خصائص المسند\" ١/ ٢٣"],[894,"الجزء: 15 - الصفحة: 487"],[895,"فصل: ما جاء في \"غريب الحديث\" لأبي عبيد"],[896,"قال أبو داود: قلتُ لأحمد: كتابةُ كتابِ \"الغريب\" الذي وضعهُ القاسمُ ابن سلامٍ؟"],[897,"قال: قد كثَّرهُ جدًّا؛ يشغلُ الإِنسان عن معرفِة العلمِ، لو كان تركهُ على ما كان أولًا؟ !"],[898,"\"مسائل أبي داود\" (١٨١٨)"],[899,"قال ابن هانئ: قيل له: كتاب أبي عبيد \"غريب الحديث\"؟"],[900,"قال: ذلك شيء حكاه عن قوم أعراب."],[901,"\"مسائل ابن هانئ\" (١٩٢٤)"],[902,"الجزء: 15 - الصفحة: 488"],[903,"أخطاء طباعية واستدراكات"],[904,"لوحظ الأخطاء الآتية في \"الجامع لعلوم الإمام\" بعد الطباعة (*)"],[905,"(*) قال مُعِدُّ الكتاب للشاملة: وقد تم استدراكها في مواطنها من هذه النسخة الإلكترونية"],[906,"الجزء: 21 - الصفحة: 247"],[907,"المجلد الخامس عشر"],[908,"صـ ٤٣٤ / س ٦: \"لم تأتيني\" تعدل: \"لم تأتني\"."],[909,"صـ ٤٣٨ / س: \"بيَّن أمره\" تعدل: \"بيِّن أمره\"."],[910,"الجزء: 21 - الصفحة: 254"],[911,"المجلد السابع عشر"],[912,"صـ ٧٥: رواية أبو أحمد الحاكم في آخر الصفحة تحذف لانقطاع السند، فأبو أحمد ولد ٢٩٠ هـ."],[913,"صـ ٩٥: رواية أبو القاسم الطبري تحذف لانقطاع الرواية."],[914,"صـ ٤٢٤/ س ٣: \"يخوي\" تعدل: \"أن يخوي\"."],[915,"صـ ٣٩٨/ س ١٣: \"يقول: ليث بن أبي سليم\" تعدل: \"يقول لليث بن أبي سليم\"."],[916,"صـ ٥١٠/ س ١٣: \"سمرون\" تعدل: \"يسمرون\"."],[917,"المجلد الثامن عشر"],[918,"ص ٦٠٢/ س ١٠: \"المخزومي\" تعدل: \"المخرمي\"."],[919,"المجلد العشرون"],[920,"صـ ٢٠/ س ٨: \"قال الفضل\" تعدل: \"قال الفضل بن زياد\"."],[921,"صـ ٣١/ س ٦: يوضع نقطتين: بعد قلت، وتحذف بعد هذا."],[922,"صـ ٧٤/ س ٨: \"إلي\" تعدل: \"إلى\"."],[923,"صـ ٩٤/ س ١١: يزال سمك الخط من على: \"قلت: بمن أكتني\"."],[924,"صـ ١١٤/ س ١٨: \"قال: على\" تعدل: \"قال علي\"."],[925,"صـ ١٣٦/ س ١٢: تحذف الفصلة بعد أريد."],[926,"صـ ١٤٩/ س ٩: \"خرسان\" تعدل: \"خراسان\"."],[927,"صـ ١٥٢/ س ٤: \"سال\" تعدل: \"سأل\"."],[928,"صـ ١٥٧/ س ٣: \"حاجا\" تعدل: \"حاجًّا\"."],[929,"صـ ١٧٠/ س ٦: يزال التشكيل من على ش يشمت."],[930,"صـ ١٧٢/ س الأخير: \"بجاله\" تعدل: \"بجالة\"."],[931,"صـ ١٨٧/ س ١٣: \"أروه\" تعدل: \"اروه\"."],[932,"صـ ٢١٩/ س ١٧: \"وردئًا\" تعدل: \"وردءًا\"."],[933,"صـ ٢٢٣ / س ٦: \"سنا\" تعدل: \"سنًّا\"."],[934,"الجزء: 21 - الصفحة: 255"],[935,"صـ ٢٣٥/ س ٦: ينقل التشكيل من على س سمع إلى ميمها."],[936,"صـ ٢٤٢/ س الرابع: \"مالك\" تعدل: \"ما لك\"."],[937,"صـ ٣٩٤: التخريج الموجود في هامش ١، ٢ للحديث: \"لو أنكم تتوكلون على اللَّه. . \"، أما الحديث: \"أنفق بلال. . . \" لم يخرج."],[938,"صـ ٣٧٤/ س ٧: \"وفى الحياة\" تعدل: \"وفي الحياة\"."],[939,"صـ ٥٤٧/ س ١٥: \"نادي لسليمان\" تعدل: \"نادى سليمان\""],[940,"الجزء: 21 - الصفحة: 256"]]);
